window.GUIDE_DATA = {"title":"Guia do Contribuinte · Aracaju","versionDate":"30/09/2026","topicCount":322,"chapterCount":31,"draft":true,"chapters":[{"number":1,"id":"capitulo-01","short":"Conheça a SEMFAZ","title":"Secretaria Municipal da Fazenda","description":"Quem administra os tributos municipais, como localizar os setores e onde consultar a legislação.","subtitle":"Administração tributária e atendimento","icon":"building","originalTitle":"SECRETARIA MUNICIPAL DE FINANÇAS E DESENVOLVIMENTO ECONÔMICO - SF","sourcePage":1,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-001","sourceId":1,"title":"O que faz a SEMFAZ e como localizar suas áreas?","originalTitle":"O que faz a SF e quais são suas unidades?","sourcePage":1,"answer":"A Secretaria Municipal da Fazenda (SEMFAZ) coordena a administração tributária e financeira de Aracaju. Para assuntos de tributos, identifique se sua demanda é imobiliária, relacionada à atividade econômica, à cobrança ou ao atendimento; o encaminhamento deve seguir a estrutura vigente da Secretaria.","review":false},{"id":"pergunta-002","sourceId":2,"title":"Como localizar os setores de administração tributária?","originalTitle":"Quais são as unidades da SUREM?","sourcePage":1,"answer":"A SUREM é uma unidade citada no guia de São Paulo. Em Aracaju, consulte a estrutura institucional da SEMFAZ para localizar o setor responsável por cadastro imobiliário, ISS, fiscalização, arrecadação e atendimento, sem utilizar as siglas de organização paulistanas.","review":false},{"id":"pergunta-003","sourceId":3,"title":"Quais são os tributos municipais tratados pela SEMFAZ?","originalTitle":"Quais são os tributos administrados pela SUREM - SF?","sourcePage":2,"answer":"Os principais assuntos deste guia são IPTU, ITBI, ISS, taxas municipais e contribuições. A cobrança de cada tributo depende da legislação de Aracaju e de sua situação específica; consulte o documento de lançamento para identificar a receita e o exercício.","review":false},{"id":"pergunta-004","sourceId":4,"title":"Onde consultar a legislação tributária de Aracaju?","originalTitle":"Qual a legislação sobre os tributos administrados pela SUREM - SF?","sourcePage":2,"answer":"A referência municipal é a Lei nº 1.547/1989, que institui o Código Tributário de Aracaju, com suas alterações e regulamentos. Também devem ser observadas a Constituição, o Código Tributário Nacional e as leis nacionais aplicáveis, como a legislação do ISS e do Simples Nacional.","review":false}]},{"number":2,"id":"capitulo-02","short":"IPTU","title":"Cálculo e pagamento do IPTU","description":"Entenda o lançamento, o valor venal, as guias e as condições de pagamento do imposto do seu imóvel.","subtitle":"Imposto sobre a Propriedade Predial e Territorial Urbana","icon":"home","originalTitle":"IMPOSTO PREDIAL E TERRITORIAL URBANO - IPTU","sourcePage":3,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-006","sourceId":6,"title":"O que é o IPTU?","originalTitle":"O que é o IPTU?","sourcePage":3,"answer":"O IPTU é o Imposto sobre a Propriedade Predial e Territorial Urbana. Incide sobre imóveis enquadrados nas condições legais de tributação urbana e é lançado pelo município com base no cadastro imobiliário.","review":false},{"id":"pergunta-007","sourceId":7,"title":"O que é imóvel construído e imóvel não construído?","originalTitle":"O que é imóvel construído e imóvel não construído?","sourcePage":3,"answer":"Imóvel construído é aquele com edificação considerada no cadastro fiscal. Imóvel não construído é, em termos gerais, o terreno sem edificação tributável; a classificação concreta depende das condições do imóvel e dos critérios municipais.","review":false},{"id":"pergunta-008","sourceId":8,"title":"O IPTU pode ser cobrado de imóveis irregulares?","originalTitle":"O IPTU pode ser cobrado de imóveis irregulares?","sourcePage":3,"answer":"A cobrança do IPTU pode alcançar imóvel com irregularidades urbanísticas ou documentais. O lançamento e o pagamento do imposto não regularizam a construção nem comprovam, por si só, a propriedade do imóvel.","review":false},{"id":"pergunta-009","sourceId":9,"title":"O que é excesso de área ou área de terreno não incorporada?","originalTitle":"O que é excesso de área ou área de terreno não incorporada?","sourcePage":3,"answer":"O guia paulista trata da parte do terreno que excede os limites considerados como incorporados à construção. A existência desse tratamento e os critérios de área em Aracaju precisam ser conferidos na legislação local antes de aplicar qualquer divisão ou alíquota diferenciada.","review":true},{"id":"pergunta-010","sourceId":10,"title":"Como é feito o cálculo do IPTU?","originalTitle":"Como é feito o cálculo do IPTU?","sourcePage":4,"answer":"Em linhas gerais, o IPTU resulta da aplicação da alíquota legal sobre o valor venal cadastrado, com os ajustes e benefícios previstos para o exercício. Confira no lançamento os dados do terreno, da construção, o uso do imóvel e os critérios municipais utilizados.","review":false},{"id":"pergunta-011","sourceId":11,"title":"O que é o valor venal do imóvel?","originalTitle":"O que é o valor venal do imóvel?","sourcePage":4,"answer":"Valor venal é o valor atribuído ao imóvel para fins tributários, conforme os critérios legais de avaliação. Ele não é necessariamente igual ao preço pedido pelo proprietário ou ao valor de uma negociação particular.","review":false},{"id":"pergunta-012","sourceId":12,"title":"Como é calculado o valor venal do terreno?","originalTitle":"Como é calculado o valor venal do terreno?","sourcePage":4,"answer":"A avaliação do terreno considera características como área, localização e fatores previstos na legislação e nas tabelas municipais. Para conferir um lançamento, solicite os dados cadastrais e a memória de cálculo utilizados na avaliação do seu imóvel.","review":false},{"id":"pergunta-013","sourceId":13,"title":"Como é calculado o valor venal da construção?","originalTitle":"Como é calculado o valor venal da construção?","sourcePage":4,"answer":"A avaliação da construção considera a área edificada e os critérios municipais de tipo, padrão, uso, conservação e outros fatores aplicáveis. Divergências entre o cadastro e a situação real devem ser demonstradas em pedido de revisão cadastral ou tributária.","review":false},{"id":"pergunta-014","sourceId":14,"title":"Como é atualizado o valor venal do imóvel e o valor do IPTU?","originalTitle":"Como é atualizado o valor venal do imóvel e o valor do IPTU?","sourcePage":5,"answer":"A atualização deve seguir a legislação e os atos municipais de cada exercício. Consulte a tabela e o lançamento atuais: os índices, limites e critérios de atualização de São Paulo em 2013 não devem ser utilizados para calcular o IPTU de Aracaju.","review":false},{"id":"pergunta-015","sourceId":15,"title":"O que é e como obter o calendário do IPTU?","originalTitle":"O que é e como obter o calendário do IPTU?","sourcePage":5,"answer":"Consulte o calendário do exercício no portal oficial da SEMFAZ e confira as datas também no seu Documento de Arrecadação Municipal (DAM). O calendário pode distinguir cota única, parcelas e situações específicas de lançamento.","review":false},{"id":"pergunta-016","sourceId":16,"title":"Como, quando e onde é feita a entrega das notificações do IPTU?","originalTitle":"Como, quando e onde é feita a entrega das notificações do IPTU?","sourcePage":6,"answer":"Mantenha seus dados de contato e o endereço do imóvel atualizados e acompanhe o lançamento pelos canais oficiais. O formato de envio e de ciência deve seguir a regra municipal; a falta de recebimento de correspondência não deve ser tratada como alteração automática do vencimento.","review":true},{"id":"pergunta-017","sourceId":17,"title":"Como emitir a 2ª via da notificação do IPTU?","originalTitle":"Como emitir a 2ª via da notificação do IPTU?","sourcePage":6,"answer":"Consulte o lançamento vinculado à inscrição imobiliária pelos serviços oficiais. Se precisar da notificação completa, de informações de cálculo ou de documento que não esteja disponível, solicite atendimento à SEMFAZ identificando imóvel e exercício.","review":false},{"id":"pergunta-018","sourceId":18,"title":"Qual é o dia de vencimento do IPTU?","originalTitle":"Qual é o dia de vencimento do IPTU?","sourcePage":6,"answer":"A data válida é a indicada no calendário municipal e no DAM do seu imóvel. Não utilize datas do guia paulista; em caso de divergência entre documentos, confirme o vencimento com a SEMFAZ antes de efetuar o pagamento.","review":false},{"id":"pergunta-019","sourceId":19,"title":"Quem é responsável pela pontualidade dos pagamentos?","originalTitle":"Quem é responsável pela pontualidade dos pagamentos?","sourcePage":6,"answer":"O contribuinte deve acompanhar o lançamento e pagar dentro do prazo. Proprietários, possuidores e representantes devem organizar a conferência das guias; contratos particulares não alteram, por si só, a responsabilidade tributária prevista em lei.","review":false},{"id":"pergunta-020","sourceId":20,"title":"Quem é o contribuinte do IPTU?","originalTitle":"Quem é o contribuinte do IPTU?","sourcePage":6,"answer":"Em termos gerais, pode ser contribuinte o proprietário, o titular do domínio útil ou o possuidor nas condições legais. A identificação do responsável no cadastro deve refletir a situação jurídica do imóvel e os critérios do Código Tributário municipal.","review":false},{"id":"pergunta-021","sourceId":21,"title":"Qual o valor a pagar após o vencimento do IPTU?","originalTitle":"Qual o valor a pagar após o vencimento do IPTU?","sourcePage":7,"answer":"Após o vencimento, podem ser devidos multa, juros e atualização previstos em lei. Emita uma guia atualizada pelo canal oficial, em vez de calcular encargos com percentuais do guia de São Paulo ou pagar um documento vencido sem confirmação.","review":false},{"id":"pergunta-022","sourceId":22,"title":"Quais os outros custos a pagar após a inscrição do débito do IPTU na Dívida Ativa?","originalTitle":"Quais os outros custos a pagar após a inscrição do débito do IPTU na Dívida Ativa?","sourcePage":7,"answer":"A inscrição em dívida ativa pode levar a protesto, cobrança administrativa ou judicial e encargos correspondentes. Consulte a situação do débito e o valor atualizado no órgão responsável; os custos dependem da fase e da modalidade de cobrança.","review":false},{"id":"pergunta-023","sourceId":23,"title":"Qual a vantagem de pagar o IPTU de uma só vez?","originalTitle":"Qual a vantagem de pagar o IPTU de uma só vez?","sourcePage":7,"answer":"O pagamento em cota única pode oferecer desconto quando previsto para o exercício, além de encerrar o pagamento anual em uma única operação. Confira o percentual, o prazo e as condições no calendário atual de Aracaju; o desconto não é permanente.","review":false},{"id":"pergunta-024","sourceId":24,"title":"Como pagar o IPTU?","originalTitle":"Como pagar o IPTU?","sourcePage":7,"answer":"Emita o DAM correto, confira inscrição imobiliária, exercício, valor e vencimento, e utilize a modalidade de pagamento aceita no documento. Guarde o comprovante e, após o processamento, acompanhe a baixa do débito.","review":false},{"id":"pergunta-025","sourceId":25,"title":"Onde pagar o IPTU?","originalTitle":"Onde pagar o IPTU?","sourcePage":8,"answer":"Utilize a rede ou os meios de pagamento autorizados na guia municipal. Confira a identificação do beneficiário e evite boletos recebidos de origem desconhecida; dúvidas sobre canais aceitos devem ser verificadas com a SEMFAZ.","review":false},{"id":"pergunta-026","sourceId":26,"title":"Como emitir a 2ª via da guia de recolhimento do IPTU?","originalTitle":"Como emitir a 2ª via da guia de recolhimento do IPTU?","sourcePage":8,"answer":"Acesse o serviço oficial de emissão de guia, identifique o imóvel e selecione o exercício ou a parcela desejada. Se a guia não estiver disponível, informe a inscrição imobiliária no atendimento; dívida ativa ou parcelamento podem exigir um canal próprio.","review":false}]},{"number":3,"id":"capitulo-03","short":"Serviços de imóveis e IPTU","title":"Serviços relacionados a imóveis e IPTU","description":"Consulta de débitos, revisão de valores, informações de endereço e outras solicitações sobre o imóvel.","subtitle":"Consultas e solicitações imobiliárias","icon":"map","originalTitle":"PRINCIPAIS SERVIÇOS RELACIONADOS A IMÓVEIS E IPTU","sourcePage":9,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-028","sourceId":28,"title":"Como consultar se o imóvel tem dívidas do IPTU?","originalTitle":"Como consultar se o imóvel tem dívidas do IPTU?","sourcePage":9,"answer":"Consulte os débitos vinculados à inscrição imobiliária e, quando necessário, solicite uma certidão. Diferencie a consulta de pagamentos e pendências da certidão que comprova a situação fiscal para uma finalidade específica.","review":false},{"id":"pergunta-029","sourceId":29,"title":"Como reclamar de incorreções de dados do IPTU?","originalTitle":"Como reclamar de incorreções de dados do IPTU?","sourcePage":9,"answer":"Identifique o dado incorreto e apresente pedido de revisão ou atualização com documentos que demonstrem a situação correta. Informe inscrição, exercício e motivo do pedido; confirme o prazo e os efeitos da solicitação sobre a cobrança.","review":false},{"id":"pergunta-030","sourceId":30,"title":"O que fazer se na Notificação de Lançamento do IPTU o imóvel aparecer com valor acima do real?","originalTitle":"O que fazer se na Notificação de Lançamento do IPTU o imóvel aparecer com valor acima do real?","sourcePage":9,"answer":"Compare os dados do lançamento com área, uso e características reais do imóvel. Se houver divergência, apresente pedido fundamentado com documentação e, quando cabível, avaliação técnica; o preço de venda isolado não substitui a análise fiscal.","review":false},{"id":"pergunta-031","sourceId":31,"title":"Como solicitar uma avaliação especial do imóvel?","originalTitle":"Como solicitar uma avaliação especial do imóvel?","sourcePage":9,"answer":"Solicite à SEMFAZ orientação sobre a modalidade adequada de revisão da avaliação. Prepare a identificação do imóvel, a justificativa e os elementos técnicos que sustentam o pedido; a vistoria e os documentos exigidos dependem da análise municipal.","review":true},{"id":"pergunta-032","sourceId":32,"title":"Como fornecer outro endereço para entrega do IPTU, de imóvel construído, nos anos seguintes?","originalTitle":"Como fornecer outro endereço para entrega do IPTU, de imóvel construído, nos anos seguintes?","sourcePage":10,"answer":"Peça a atualização do endereço de correspondência e dos contatos no cadastro, comprovando a representação do interessado quando necessário. Confira no protocolo se a alteração foi aceita e a partir de qual lançamento será utilizada.","review":false},{"id":"pergunta-033","sourceId":33,"title":"O que deve fazer a administradora de imóveis para receber as notificações do IPTU de seus clientes?","originalTitle":"O que deve fazer a administradora de imóveis para receber as notificações do IPTU de seus clientes?","sourcePage":11,"answer":"A administradora deve comprovar que está autorizada a representar cada contribuinte. Antes de solicitar recebimento de notificações em seu endereço, confirme com a SEMFAZ se existe procedimento específico para administração de múltiplos imóveis.","review":true},{"id":"pergunta-034","sourceId":34,"title":"Onde as administradoras de imóveis deverão entregar os documentos e receber as notificações do IPTU de seus clientes?","originalTitle":"Onde as administradoras de imóveis deverão entregar os documentos e receber as notificações do IPTU de seus clientes?","sourcePage":11,"answer":"O procedimento de entrega e retirada em lotes descrito no PDF é de São Paulo. Em Aracaju, consulte o atendimento da SEMFAZ para definir o canal e a documentação aplicáveis à administradora, sem encaminhar documentos às unidades paulistanas.","review":true},{"id":"pergunta-035","sourceId":35,"title":"Como obter informações sobre denominação atual e/ou anterior de vias públicas do cadastro de logradouros?","originalTitle":"Como obter informações sobre denominação atual e/ou anterior de vias públicas do cadastro de logradouros?","sourcePage":12,"answer":"A identificação do logradouro pode ser pesquisada nas informações municipais de endereço e cartografia. Para documento com valor comprobatório, solicite orientação sobre certidão ou informação oficial de denominação, indicando localização e nomes conhecidos da via.","review":false},{"id":"pergunta-036","sourceId":36,"title":"Como obter a inscrição imobiliária do imóvel?","originalTitle":"Como obter o número do contribuinte (SQL)?","sourcePage":12,"answer":"Procure a inscrição imobiliária em um DAM ou documento cadastral do imóvel. Se não a localizar, apresente endereço e documentos do imóvel à SEMFAZ; SQL é a denominação usada no guia de São Paulo, e não deve ser exigida como código de Aracaju.","review":false},{"id":"pergunta-037","sourceId":37,"title":"Como cadastrar os imóveis rurais?","originalTitle":"Como cadastrar os imóveis rurais?","sourcePage":12,"answer":"Imóvel rural pode envolver obrigações federais de cadastro e ITR, além de registros municipais eventualmente necessários. A definição do tributo e do cadastro depende da localização, destinação e enquadramento legal; confirme a situação antes de pedir inscrição para IPTU.","review":true},{"id":"pergunta-038","sourceId":38,"title":"Como deve proceder o proprietário do imóvel para não se submeter à cobrança do IPTU progressivo?","originalTitle":"Como deve proceder o proprietário do imóvel para não se submeter à cobrança do IPTU progressivo?","sourcePage":13,"answer":"O IPTU progressivo no tempo depende dos instrumentos urbanísticos e da notificação legalmente aplicáveis. Se houver notificação, consulte o órgão municipal competente e cumpra as exigências específicas de parcelamento, edificação ou utilização, dentro dos prazos indicados.","review":true},{"id":"pergunta-039","sourceId":39,"title":"Como esclarecer dúvidas?","originalTitle":"Como esclarecer dúvidas?","sourcePage":13,"answer":"Reúna inscrição imobiliária, exercício e descrição objetiva da dúvida. Utilize os canais da SEMFAZ ou o atendimento agendado, quando exigido; documentos completos ajudam a direcionar a demanda ao setor correto.","review":false}]},{"number":4,"id":"capitulo-04","short":"Documentos de imóveis","title":"Documentos para solicitações imobiliárias","description":"Prepare a documentação para alterações físicas, divisão, unificação e outros pedidos relativos ao imóvel.","subtitle":"Documentação e representação","icon":"folder","originalTitle":"DOCUMENTOS NECESSÁRIOS A SEREM INCLUÍDOS NOS PRINCIPAIS PEDIDOS RELACIONADOS A IMÓVEIS E IPTU","sourcePage":13,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-041","sourceId":41,"title":"Quais os documentos necessários a serem incluídos em todo e qualquer pedido relacionado a IPTU e imóveis?","originalTitle":"Quais os documentos necessários a serem incluídos em todo e qualquer pedido relacionado a IPTU e imóveis?","sourcePage":14,"answer":"Como preparação, reúna identificação do interessado, inscrição imobiliária, documento do imóvel e procuração quando houver representante. A lista obrigatória deve ser confirmada no serviço municipal escolhido, pois varia conforme o tipo de pedido.","review":false},{"id":"pergunta-042","sourceId":42,"title":"Quais os demais documentos a serem incluídos nos pedidos de alteração de dados físicos do imóvel?","originalTitle":"Quais os demais documentos a serem incluídos nos pedidos de alteração de dados físicos do imóvel?","sourcePage":14,"answer":"Alterações de área, uso ou características podem exigir planta, levantamento, documentos da obra e responsabilidade técnica, conforme o caso. Apresente elementos que permitam comparar o cadastro com a situação real e confirme a relação exigida pelo município.","review":false},{"id":"pergunta-043","sourceId":43,"title":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Imóvel Construído?","originalTitle":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Imóvel Construído?","sourcePage":14,"answer":"O desmembramento de imóvel construído pode exigir aprovação urbanística, plantas, documentos registrais e identificação das novas unidades. A abertura de inscrições fiscais depende da análise municipal e não substitui a regularização no registro imobiliário.","review":true},{"id":"pergunta-044","sourceId":44,"title":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Terreno?","originalTitle":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Terreno?","sourcePage":14,"answer":"Para divisão de terreno, reúna os documentos da propriedade e a aprovação ou o projeto de parcelamento, quando exigidos. Confirme com a SEMFAZ e o órgão urbanístico como a divisão aprovada será refletida no cadastro fiscal.","review":true},{"id":"pergunta-045","sourceId":45,"title":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Apartamento ou Garagem determinada?","originalTitle":"Quais os demais documentos a serem incluídos nos pedidos de Desdobro Fiscal de Apartamento ou Garagem determinada?","sourcePage":14,"answer":"Unidades autônomas e garagens devem ser identificadas pelos documentos do condomínio e do registro, inclusive áreas e frações quando aplicáveis. O município analisará se há fundamento para inscrições separadas; uma divisão de uso informal não basta para criar autonomia fiscal.","review":true},{"id":"pergunta-046","sourceId":46,"title":"Quais os demais documentos a serem incluídos nos pedidos de Englobamento Fiscal?","originalTitle":"Quais os demais documentos a serem incluídos nos pedidos de Englobamento Fiscal?","sourcePage":15,"answer":"A unificação fiscal pode exigir documentos registrais, planta da área resultante e comprovação de que os imóveis podem ser tratados como uma unidade. Confirme o procedimento local de unificação ou remembramento antes de solicitar o ajuste cadastral.","review":true},{"id":"pergunta-047","sourceId":47,"title":"Como quitar a parte da dívida correspondente à sua fração do imóvel desdobrado, englobado ou remembrado?","originalTitle":"Como quitar a parte da dívida correspondente à sua fração do imóvel desdobrado, englobado ou remembrado?","sourcePage":15,"answer":"A divisão física ou cadastral não reparte automaticamente os débitos anteriores. Solicite análise da responsabilidade e da possibilidade de individualizar valores ou emitir guia específica; não calcule e pague uma fração por conta própria.","review":true}]},{"number":5,"id":"capitulo-05","short":"Inscrição imobiliária","title":"Inscrição imobiliária e atualização cadastral","description":"Inclusão e atualização de imóveis, titulares, endereços e características no cadastro fiscal.","subtitle":"Cadastro do imóvel e do responsável","icon":"pin","originalTitle":"INSCRIÇÃO IMOBILIÁRIA E ATUALIZAÇÃO DE DADOS CADASTRAIS","sourcePage":15,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-049","sourceId":49,"title":"Por que fazer a inscrição imobiliária e atualizar os dados do imóvel e do proprietário ou do possuidor ou do titular do domínio útil?","originalTitle":"Por que fazer a inscrição imobiliária e atualizar os dados do imóvel e do proprietário ou do possuidor ou do titular do domínio útil?","sourcePage":15,"answer":"O cadastro identifica o imóvel e o responsável e permite o lançamento e a comunicação de atos tributários. Atualizá-lo reduz divergências de área, titularidade, endereço e uso, sem substituir os atos necessários no cartório de registro.","review":false},{"id":"pergunta-050","sourceId":50,"title":"Quando o proprietário, o possuidor ou o titular do domínio útil de um imóvel deve fazer uma declaração para incluir dados de um novo imóvel no cadastro imobiliário fiscal?","originalTitle":"Quando o proprietário, o possuidor ou o titular do domínio útil de um imóvel deve fazer uma declaração para incluir dados de um novo imóvel no cadastro imobiliário fiscal?","sourcePage":16,"answer":"A inclusão deve ser solicitada quando existir imóvel ou unidade ainda não inscrita, nos casos e prazos previstos pela regra municipal. Isso pode decorrer de parcelamento, condomínio, individualização ou identificação de imóvel não cadastrado.","review":true},{"id":"pergunta-051","sourceId":51,"title":"Quando o proprietário, o possuidor ou o titular do domínio útil de um imóvel deve fazer uma declaração para alterar dados de um imóvel já inscrito no cadastro imobiliário fiscal?","originalTitle":"Quando o proprietário, o possuidor ou o titular do domínio útil de um imóvel deve fazer uma declaração para alterar dados de um imóvel já inscrito no cadastro imobiliário fiscal?","sourcePage":17,"answer":"Comunique mudanças relevantes de área, construção, utilização, endereço ou responsável, conforme as obrigações locais. Guarde os documentos e o protocolo; as datas da alteração podem influenciar a análise do lançamento.","review":true},{"id":"pergunta-052","sourceId":52,"title":"Qual o procedimento para fazer a atualização cadastral?","originalTitle":"Qual o procedimento para fazer a atualização cadastral?","sourcePage":17,"answer":"Identifique qual dado precisa ser corrigido e reúna a prova da alteração. Encaminhe o pedido pelo canal municipal indicado para cadastro imobiliário e acompanhe eventuais exigências até a conclusão.","review":false},{"id":"pergunta-053","sourceId":53,"title":"Quais os documentos de comprovação de propriedade aceitos para atualização de dados?","originalTitle":"Quais os documentos de comprovação de propriedade aceitos para atualização de dados?","sourcePage":18,"answer":"Matrícula ou certidão do registro, escritura e outros instrumentos podem documentar situações distintas de propriedade ou posse. A aceitação depende do pedido; para comprovar propriedade registrada, verifique a matrícula atualizada do imóvel.","review":false},{"id":"pergunta-054","sourceId":54,"title":"Quais os documentos necessários para protocolar as principais solicitações de alteração de dados cadastrais?","originalTitle":"Quais os documentos necessários para protocolar as principais solicitações de alteração de dados cadastrais?","sourcePage":18,"answer":"Prepare a identificação do interessado, a inscrição do imóvel e os documentos que comprovem cada alteração pedida. Acrescente procuração e documentação técnica quando cabíveis; a relação definitiva deve vir da orientação oficial do serviço.","review":false},{"id":"pergunta-055","sourceId":55,"title":"Em que a atualização dos dados cadastrais interfere na transferência de propriedade do imóvel?","originalTitle":"Em que a atualização dos dados cadastrais interfere na transferência de propriedade do imóvel?","sourcePage":19,"answer":"A atualização fiscal registra informações para a administração tributária. A transferência da propriedade imobiliária segue os requisitos civis e registrais e, em regra, depende do registro do título; alterar o nome no IPTU não substitui esse registro.","review":false}]},{"number":6,"id":"capitulo-06","short":"Descontos e incentivos","title":"Descontos e incentivos fiscais","description":"Diferencie desconto de pagamento, incentivo e benefício condicionado a legislação específica.","subtitle":"Benefícios e condições de enquadramento","icon":"percent","originalTitle":"DESCONTOS E INCENTIVOS FISCAIS","sourcePage":19,"note":"Os incentivos a entidades esportivas e projetos culturais do roteiro paulista só podem ser utilizados em Aracaju quando houver previsão municipal equivalente.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"},{"label":"Benefícios fiscais — Transparência Aracaju","url":"https://transparencia.aracaju.se.gov.br/prefeitura/prestacao-de-contas/"}],"topics":[{"id":"pergunta-057","sourceId":57,"title":"Quais os descontos que podem ser concedidos para o IPTU?","originalTitle":"Quais os descontos que podem ser concedidos para o IPTU?","sourcePage":19,"answer":"Pode haver desconto de cota única ou benefício específico previsto em lei. Confira os atos do exercício e o enquadramento do imóvel; redução, isenção, incentivo e remissão têm condições diferentes e não devem ser confundidos.","review":false},{"id":"pergunta-058","sourceId":58,"title":"Como e onde solicitar desconto do IPTU?","originalTitle":"Como e onde solicitar desconto do IPTU?","sourcePage":20,"answer":"O desconto da cota única, quando previsto, costuma estar refletido na guia emitida dentro do prazo. Benefícios que dependem de requerimento exigem pedido e comprovação do enquadramento; consulte a modalidade aplicável em Aracaju.","review":true},{"id":"pergunta-059","sourceId":59,"title":"Como verificar incentivos para agremiações, federações e confederações esportivas?","originalTitle":"O que é necessário para obter os incentivos fiscais para abatimento do Imposto Territorial Urbano sobre imóveis de propriedade das agremiações, federações e confederações desportivas sediadas no Município de São Paulo?","sourcePage":20,"answer":"O incentivo a agremiações, federações e confederações descrito no PDF depende de lei de São Paulo. Para Aracaju, é necessário identificar lei local que autorize benefício equivalente e seus requisitos; não há concessão automática por se tratar de entidade esportiva.","review":true},{"id":"pergunta-060","sourceId":60,"title":"Em que situação poderá ser concedido incentivo fiscal para a realização de projetos culturais?","originalTitle":"Em que situação poderá ser concedido incentivo fiscal para a realização de projetos culturais?","sourcePage":21,"answer":"Um incentivo tributário a projeto cultural exige fundamento legal, habilitação do projeto e cumprimento das condições do programa. A existência e o funcionamento de programa equivalente em Aracaju precisam de confirmação antes de orientar abatimentos.","review":true},{"id":"pergunta-061","sourceId":61,"title":"Quais outros incentivos fiscais previstos na legislação?","originalTitle":"Quais outros incentivos fiscais previstos na legislação?","sourcePage":21,"answer":"Os incentivos variam conforme tributo, atividade, empreendimento e legislação vigente. Consulte a base municipal de benefícios e seus atos de concessão para saber se sua situação se enquadra e quais contrapartidas são exigidas.","review":true}]},{"number":7,"id":"capitulo-07","short":"Isenção e imunidade do IPTU","title":"Isenção, imunidade e remissão do IPTU","description":"Condições para solicitar benefícios, comprovar o enquadramento e acompanhar a análise do pedido.","subtitle":"Benefícios relacionados ao imóvel","icon":"shield","originalTitle":"ISENÇÕES, IMUNIDADES E REMISSÔES DO IPTU","sourcePage":22,"note":"Os critérios, limites e documentos de isenção precisam de validação municipal. As hipóteses paulistanas de aposentadoria, enchentes e uso cultural não foram assumidas como benefícios de Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"},{"label":"Benefícios fiscais — Transparência Aracaju","url":"https://transparencia.aracaju.se.gov.br/prefeitura/prestacao-de-contas/"}],"topics":[{"id":"pergunta-063","sourceId":63,"title":"Qual a condição para solicitar isenção do IPTU?","originalTitle":"Qual a condição para solicitar isenção do IPTU?","sourcePage":22,"answer":"A isenção exige enquadramento em hipótese prevista na legislação de Aracaju e cumprimento das condições documentais e materiais. Quando não for automática, apresente requerimento no prazo municipal e acompanhe a decisão.","review":true},{"id":"pergunta-064","sourceId":64,"title":"Quem pode ser isento do Imposto Predial?","originalTitle":"Quem pode ser isento do Imposto Predial?","sourcePage":22,"answer":"O benefício depende da hipótese legal e das características do imóvel e do titular. A condição de proprietário de edificação não concede isenção por si só; consulte os critérios municipais do exercício.","review":true},{"id":"pergunta-065","sourceId":65,"title":"Quem pode ser isento do Imposto Territorial Urbano?","originalTitle":"Quem pode ser isento do Imposto Territorial Urbano?","sourcePage":23,"answer":"Terrenos só recebem isenção quando abrangidos por hipótese expressa de lei local. Benefícios destinados à residência do titular, por exemplo, não devem ser estendidos automaticamente a terrenos sem construção.","review":true},{"id":"pergunta-066","sourceId":66,"title":"Quem pode ser isento do IPTU (tanto do Imposto Predial quanto do Imposto Territorial)?","originalTitle":"Quem pode ser isento do IPTU (tanto do Imposto Predial quanto do Imposto Territorial)?","sourcePage":23,"answer":"Verifique a hipótese aplicável ao conjunto do IPTU e a extensão do benefício no ato de concessão. Aracaju publica benefícios e remissões específicos; renda, uso residencial, propriedade e outras condições devem ser analisadas conforme a norma vigente.","review":true},{"id":"pergunta-067","sourceId":67,"title":"O que é necessário para o aposentado, pensionista ou beneficiário de renda mensal vitalícia solicitar a isenção do IPTU?","originalTitle":"O que é necessário para o aposentado, pensionista ou beneficiário de renda mensal vitalícia solicitar a isenção do IPTU?","sourcePage":24,"answer":"Aposentadoria ou pensão, isoladamente, não assegura o benefício. Prepare os comprovantes de renda, residência e situação do imóvel e confirme se o enquadramento municipal atende ao seu caso; os limites paulistanos de 2013 não se aplicam.","review":true},{"id":"pergunta-068","sourceId":68,"title":"O que é necessário para as Entidades Culturais solicitarem a isenção do Imposto Predial?","originalTitle":"O que é necessário para as Entidades Culturais solicitarem a isenção do Imposto Predial?","sourcePage":25,"answer":"A condição de entidade cultural não gera automaticamente a isenção municipal. Confirme se existe hipótese legal local e, havendo, apresente estatuto, representação e documentos do imóvel e das atividades exigidos no requerimento.","review":true},{"id":"pergunta-069","sourceId":69,"title":"O que é necessário para as Sociedades Amigos de Bairros solicitarem a isenção do Imposto Predial?","originalTitle":"O que é necessário para as Sociedades Amigos de Bairros solicitarem a isenção do Imposto Predial?","sourcePage":26,"answer":"Associações de bairro precisam comprovar seu enquadramento em benefício municipal específico, se existente. A denominação usada no estatuto e a atuação comunitária não substituem a previsão legal nem a documentação do imóvel.","review":true},{"id":"pergunta-070","sourceId":70,"title":"O que é necessário para as Agremiações Desportivas solicitarem a isenção do Imposto Predial?","originalTitle":"O que é necessário para as Agremiações Desportivas solicitarem a isenção do Imposto Predial?","sourcePage":26,"answer":"Entidades esportivas devem verificar se há isenção ou incentivo local destinado à sua situação. Reúna documentos de constituição, representação, atividades e uso do imóvel, conforme a lista do serviço competente.","review":true},{"id":"pergunta-071","sourceId":71,"title":"O que é necessário para os imóveis utilizados como templos de qualquer culto solicitarem isenção do IPTU?","originalTitle":"O que é necessário para os imóveis utilizados como templos de qualquer culto solicitarem isenção do IPTU?","sourcePage":27,"answer":"Imóveis relacionados a templos podem envolver imunidade constitucional, cuja análise considera titularidade ou situação admitida pela Constituição e vínculo com as finalidades essenciais. Solicite o reconhecimento com os documentos exigidos; diferencie imunidade de isenção municipal.","review":true},{"id":"pergunta-072","sourceId":72,"title":"O que é necessário para solicitar a isenção decorrente de enchentes e alagamentos?","originalTitle":"O que é necessário para solicitar a isenção decorrente de enchentes e alagamentos?","sourcePage":27,"answer":"O benefício por enchente mencionado no guia paulista não pode ser aplicado automaticamente em Aracaju. Verifique se houve lei ou ato local para o evento, quais imóveis foram abrangidos e como comprovar os danos e a localização.","review":true},{"id":"pergunta-073","sourceId":73,"title":"O que é necessário para solicitar a isenção do IPTU para os imóveis utilizados como salas de exibição de cinematecas e cineclubes?","originalTitle":"O que é necessário para solicitar a isenção do IPTU para os imóveis utilizados como salas de exibição de cinematecas e cineclubes?","sourcePage":28,"answer":"A isenção destinada a cinematecas e cineclubes é uma hipótese específica do roteiro paulista. Para utilizá-la em Aracaju, seria necessário fundamento legal municipal e atendimento aos respectivos requisitos de funcionamento e uso do imóvel.","review":true},{"id":"pergunta-074","sourceId":74,"title":"Quais imóveis podem solicitar reconhecimento de imunidade do IPTU?","originalTitle":"Quais imóveis podem solicitar reconhecimento de imunidade do IPTU?","sourcePage":28,"answer":"A imunidade decorre da Constituição e pode abranger imóveis vinculados a pessoas e finalidades constitucionalmente protegidas. A situação concreta exige análise do titular, do uso e dos requisitos aplicáveis; imunidade não equivale a dispensa geral de qualquer tributo.","review":false},{"id":"pergunta-075","sourceId":75,"title":"O que é necessário para solicitar o reconhecimento da imunidade do IPTU?","originalTitle":"O que é necessário para solicitar o reconhecimento da imunidade do IPTU?","sourcePage":29,"answer":"Apresente requerimento que identifique o fundamento constitucional, o imóvel e o vínculo com a finalidade protegida. Documentos de constituição, representação, registro e uso devem seguir a relação exigida na análise municipal.","review":true},{"id":"pergunta-076","sourceId":76,"title":"Em que caso a Prefeitura poderá perdoar a dívida de IPTU?","originalTitle":"Em que caso a Prefeitura poderá perdoar a dívida de IPTU?","sourcePage":29,"answer":"O perdão de crédito tributário, chamado remissão, depende de autorização legal e das condições do programa ou da hipótese municipal. Não decorre apenas da dificuldade de pagamento; solicite análise quando houver previsão aplicável.","review":true},{"id":"pergunta-077","sourceId":77,"title":"Onde solicitar informações sobre o andamento dos processos de pedido de isenção e de imunidade?","originalTitle":"Onde solicitar informações sobre o andamento dos processos de pedido de isenção e de imunidade?","sourcePage":30,"answer":"Acompanhe o processo pelo número do protocolo e confira exigências ou comunicações recebidas. Se o acompanhamento eletrônico não esclarecer a situação, informe o protocolo no atendimento da SEMFAZ.","review":false}]},{"number":8,"id":"capitulo-08","short":"ITBI","title":"Transmissão de imóveis e ITBI","description":"Orientações sobre transmissão onerosa, avaliação, guia de pagamento e análise de benefícios.","subtitle":"Imposto sobre a Transmissão de Bens Imóveis","icon":"key","originalTitle":"IMPOSTO SOBRE TRANSMISSÃO DE BENS IMÓVEIS – ITBI","sourcePage":30,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-079","sourceId":79,"title":"O que é o ITBI?","originalTitle":"O que é o ITBI?","sourcePage":30,"answer":"O ITBI é o imposto municipal sobre transmissões entre pessoas vivas, por ato oneroso, de bens imóveis e de direitos abrangidos pela lei. Sua análise depende da natureza da operação, do imóvel e das exceções legais.","review":false},{"id":"pergunta-080","sourceId":80,"title":"O que é transmissão “inter-vivos”?","originalTitle":"O que é transmissão “inter-vivos”?","sourcePage":30,"answer":"Transmissão inter vivos é aquela realizada entre pessoas vivas. Diferencia-se da transmissão por falecimento; doações e heranças também precisam ser distinguidas das operações onerosas sujeitas ao ITBI.","review":false},{"id":"pergunta-081","sourceId":81,"title":"O que é ato oneroso?","originalTitle":"O que é ato oneroso?","sourcePage":30,"answer":"Ato oneroso é um negócio que envolve contrapartida econômica, como pagamento ou permuta. A existência de preço não resolve sozinha a tributação: é necessário identificar o direito transmitido e a hipótese legal.","review":false},{"id":"pergunta-082","sourceId":82,"title":"Em quais negócios “inter-vivos” e onerosos o ITBI é devido?","originalTitle":"Em quais negócios “inter-vivos” e onerosos o ITBI é devido?","sourcePage":30,"answer":"Compra e venda, permuta e transmissão onerosa de determinados direitos podem estar no campo de incidência do ITBI. A operação deve ser examinada individualmente, pois existem exceções, imunidades e situações cuja tributação exige análise jurídica.","review":false},{"id":"pergunta-083","sourceId":83,"title":"Quem deve pagar o ITBI?","originalTitle":"Quem deve pagar o ITBI?","sourcePage":31,"answer":"O contribuinte e os responsáveis devem ser identificados conforme a lei municipal e o negócio realizado. Consulte a guia e a orientação do ITBI de Aracaju; os ajustes entre comprador e vendedor não substituem a responsabilidade definida em lei.","review":true},{"id":"pergunta-084","sourceId":84,"title":"Como é feito o cálculo do ITBI?","originalTitle":"Como é feito o cálculo do ITBI?","sourcePage":31,"answer":"O cálculo aplica a alíquota legal à base de cálculo apurada para a transmissão, com eventual tratamento específico da operação. Confira a memória da guia emitida; alíquotas e regras de financiamento do manual paulista não devem ser reproduzidas.","review":true},{"id":"pergunta-085","sourceId":85,"title":"Qual a base de cálculo do ITBI?","originalTitle":"Qual a base de cálculo do ITBI?","sourcePage":32,"answer":"A base deve observar o valor de mercado e o procedimento legal aplicável à transmissão. Havendo divergência de avaliação, solicite a fundamentação e a memória de cálculo para exercer o direito de contestação.","review":true},{"id":"pergunta-086","sourceId":86,"title":"O que o contribuinte poderá fazer caso considere que o valor, apurado pela Prefeitura, está em desacordo com o valor de mercado?","originalTitle":"O que o contribuinte poderá fazer caso considere que o valor, apurado pela Prefeitura, está em desacordo com o valor de mercado?","sourcePage":32,"answer":"Apresente pedido de revisão com a identificação da transação e os documentos que sustentam o valor informado, inclusive elementos de mercado quando cabíveis. Confirme o prazo e acompanhe a análise antes de assumir que o valor da guia foi alterado.","review":false},{"id":"pergunta-087","sourceId":87,"title":"O que fazer em caso de perda ou extravio da guia de recolhimento do ITBI?","originalTitle":"O que fazer em caso de perda ou extravio da guia de recolhimento do ITBI?","sourcePage":33,"answer":"Solicite nova emissão pelo serviço oficial de ITBI ou pelo atendimento, usando os dados da transação e da guia. Verifique se houve atualização de valor ou vencimento antes de efetuar o pagamento.","review":false},{"id":"pergunta-088","sourceId":88,"title":"Quem deve apresentar os dados da transação imobiliária?","originalTitle":"Quem deve apresentar a Declaração de Transação Imobiliária – DTI?","sourcePage":33,"answer":"Em Aracaju, utilize a declaração ou solicitação exigida no serviço municipal de ITBI, apresentada pelo interessado ou representante habilitado. A sigla DTI e o formulário descritos no PDF correspondem ao procedimento paulista e não devem ser exigidos sem base local.","review":true},{"id":"pergunta-089","sourceId":89,"title":"Qual o prazo para pagamento do ITBI?","originalTitle":"Qual o prazo para pagamento do ITBI?","sourcePage":34,"answer":"Siga o vencimento da guia e as condições do procedimento municipal para a operação. Confirme também a documentação necessária para a lavratura ou o registro do título; os prazos de São Paulo não se aplicam.","review":true},{"id":"pergunta-090","sourceId":90,"title":"Quais são os valores que deverão ser pagos após o prazo estabelecido?","originalTitle":"Quais são os valores que deverão ser pagos após o prazo estabelecido?","sourcePage":34,"answer":"A guia fora do prazo pode receber os encargos previstos na legislação local. Solicite documento atualizado e confirme se a avaliação ou o procedimento da transação também precisa ser renovado.","review":false},{"id":"pergunta-091","sourceId":91,"title":"Em que caso o ITBI pode ser parcelado?","originalTitle":"Em que caso o ITBI pode ser parcelado?","sourcePage":34,"answer":"A possibilidade de parcelamento deve ser confirmada para a modalidade da transação e o débito. Consulte o serviço específico de parcelamento de ITBI e verifique número de parcelas, entrada e efeitos sobre o documento de quitação.","review":true},{"id":"pergunta-092","sourceId":92,"title":"Onde obter a guia de recolhimento do ITBI?","originalTitle":"Onde obter a guia de recolhimento do ITBI?","sourcePage":35,"answer":"Use o canal municipal indicado para ITBI e forneça os dados do imóvel, das partes e da operação. A emissão da guia depende da análise ou declaração exigida pelo procedimento local.","review":false},{"id":"pergunta-093","sourceId":93,"title":"Quando o ITBI não é devido?","originalTitle":"Quando o ITBI não é devido?","sourcePage":35,"answer":"Pode não haver incidência quando o negócio estiver fora da hipótese do ITBI ou se enquadrar em proteção constitucional ou legal. Doação, herança e reorganizações societárias exigem distinção entre tributos e análise das condições próprias.","review":true},{"id":"pergunta-094","sourceId":94,"title":"O que se analisa para estabelecer a atividade preponderante do adquirente para efeitos de não-incidência do ITBI?","originalTitle":"O que se analisa para estabelecer a atividade preponderante do adquirente para efeitos de não-incidência do ITBI?","sourcePage":35,"answer":"Quando a norma exigir análise de atividade preponderante, são examinadas a atividade e as receitas da pessoa jurídica no período legal. Apresente demonstrações e documentos pedidos; a simples descrição do objeto social pode não resolver o enquadramento.","review":true},{"id":"pergunta-095","sourceId":95,"title":"Qual a forma de solicitar a não-incidência do ITBI?","originalTitle":"Qual a forma de solicitar a não-incidência do ITBI?","sourcePage":36,"answer":"Solicite análise formal da operação com o fundamento invocado e a documentação societária e imobiliária pertinente. O reconhecimento depende da autoridade competente e das condições legais, não de declaração unilateral do interessado.","review":true},{"id":"pergunta-096","sourceId":96,"title":"Quais são os casos de imunidade do ITBI?","originalTitle":"Quais são os casos de imunidade do ITBI?","sourcePage":36,"answer":"A Constituição prevê situações de imunidade relacionadas à transmissão e à natureza do adquirente ou da operação. A extensão e as exceções precisam ser verificadas no caso concreto, inclusive em integralização de capital e reorganização societária.","review":true},{"id":"pergunta-097","sourceId":97,"title":"O que é necessário para solicitar o reconhecimento da imunidade do ITBI?","originalTitle":"O que é necessário para solicitar o reconhecimento da imunidade do ITBI?","sourcePage":36,"answer":"Reúna os documentos da operação, do imóvel, das partes e do fundamento da imunidade. Quando houver pessoa jurídica, podem ser necessários atos societários e demonstrações contábeis; confirme a lista oficial do serviço.","review":true},{"id":"pergunta-098","sourceId":98,"title":"Quais são os casos de isenção do ITBI?","originalTitle":"Quais são os casos de isenção do ITBI?","sourcePage":37,"answer":"Isenções dependem de lei municipal específica e do enquadramento da operação. Aracaju publica hipóteses vinculadas, entre outras situações, a programas habitacionais; consulte a lei aplicável, sem utilizar a lista paulista como regra local.","review":true},{"id":"pergunta-099","sourceId":99,"title":"O que é necessário para solicitar a isenção do ITBI?","originalTitle":"O que é necessário para solicitar a isenção do ITBI?","sourcePage":37,"answer":"Apresente pedido com a identificação do benefício legal e os documentos que comprovem todos os requisitos. Certificados, contratos e enquadramento em programa habitacional podem ser necessários conforme a hipótese.","review":true},{"id":"pergunta-100","sourceId":100,"title":"Onde obter informações específicas sobre a forma de cálculo do ITBI?","originalTitle":"Onde obter informações específicas sobre a forma de cálculo do ITBI?","sourcePage":38,"answer":"Consulte os serviços de ITBI da SEMFAZ e solicite esclarecimento da guia ou da memória de cálculo. Tenha em mãos inscrição do imóvel, número da transação e documentos do negócio para receber orientação específica.","review":false}]},{"number":9,"id":"capitulo-09","short":"ISS: incidência","title":"ISS: incidência e responsabilidade","description":"Identifique o serviço, o contribuinte, o responsável e as situações de retenção do imposto.","subtitle":"Imposto sobre Serviços de Qualquer Natureza","icon":"briefcase","originalTitle":"IMPOSTO SOBRE SERVIÇOS DE QUALQUER NATUREZA – ISS","sourcePage":38,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-102","sourceId":102,"title":"O que é o ISS?","originalTitle":"O que é o ISS?","sourcePage":38,"answer":"O ISS é o Imposto sobre Serviços de Qualquer Natureza. Incide sobre serviços abrangidos pela lista legal, observadas as regras de local de incidência, contribuinte, responsabilidade e benefícios aplicáveis.","review":false},{"id":"pergunta-103","sourceId":103,"title":"O ISS é devido independentemente de quais situações?","originalTitle":"O ISS é devido independentemente de quais situações?","sourcePage":38,"answer":"A incidência deve ser analisada a partir da prestação e da lista de serviços, e não apenas do nome da atividade ou do cadastro. Estar sem inscrição ou licença não afasta automaticamente a obrigação; situações de exceção devem ser examinadas na norma.","review":false},{"id":"pergunta-104","sourceId":104,"title":"Quem é o contribuinte do ISS?","originalTitle":"Quem é o contribuinte do ISS?","sourcePage":39,"answer":"Em regra, o contribuinte é o prestador do serviço. A lei pode atribuir a outra pessoa a responsabilidade por recolher ou reter o imposto, sem dispensar a correta identificação da operação.","review":false},{"id":"pergunta-105","sourceId":105,"title":"Quem é o responsável tributário do ISS?","originalTitle":"Quem é o responsável tributário do ISS?","sourcePage":39,"answer":"Responsável tributário é a pessoa a quem a legislação atribui o dever de recolher o ISS em determinada situação, como certas hipóteses de contratação e retenção. Essa responsabilidade precisa de fundamento legal.","review":false},{"id":"pergunta-106","sourceId":106,"title":"Quando o responsável tributário do ISS fica desobrigado de reter e pagar o imposto?","originalTitle":"Quando o responsável tributário do ISS fica desobrigado de reter e pagar o imposto?","sourcePage":39,"answer":"A dispensa de retenção depende do enquadramento da operação e da legislação aplicável. Antes de deixar de reter, confira atividade, local do imposto, regime do prestador e documentos que comprovem eventual exceção.","review":false},{"id":"pergunta-107","sourceId":107,"title":"O que deverá ser feito por quem utilizar os serviços prestados por autônomos e sociedades de profissionais?","originalTitle":"O que deverá ser feito por quem utilizar os serviços prestados por autônomos e sociedades de profissionais?","sourcePage":40,"answer":"O tomador deve verificar a documentação do prestador, o regime de tributação e as obrigações de retenção e declaração. Recibo, nota e eventual comprovante de cadastro ou benefício devem corresponder ao serviço efetivamente contratado.","review":false},{"id":"pergunta-108","sourceId":108,"title":"Quando o tomador de serviço torna-se responsável por reter e recolher o ISS?","originalTitle":"Quando o tomador de serviço torna-se responsável por reter e recolher o ISS?","sourcePage":40,"answer":"A retenção pelo tomador ocorre nas hipóteses previstas em lei. Confira o código do serviço, o município ao qual o ISS é devido, a situação do prestador e as regras municipais, sem presumir retenção apenas por ele estar em outra cidade.","review":false},{"id":"pergunta-109","sourceId":109,"title":"Quem é considerado pessoalmente responsável pelo ISS?","originalTitle":"Quem é considerado pessoalmente responsável pelo ISS?","sourcePage":40,"answer":"A responsabilidade pessoal de terceiros depende das hipóteses legais de atuação, infração e representação. Ela não deve ser atribuída automaticamente a qualquer sócio ou empregado; casos específicos exigem análise da legislação e dos fatos.","review":false},{"id":"pergunta-110","sourceId":110,"title":"Qual o roteiro deve ser seguido para a correta aplicação da lei do ISS?","originalTitle":"Qual o roteiro deve ser seguido para a correta aplicação da lei do ISS?","sourcePage":40,"answer":"Identifique o serviço e seu código, o local ao qual o imposto é devido, o regime do prestador, a base, a alíquota e a responsabilidade pelo recolhimento. Depois, confira a emissão fiscal, a declaração e o vencimento; dúvidas de enquadramento devem ser submetidas à SEMFAZ.","review":false}]},{"number":10,"id":"capitulo-10","short":"ISS: cálculo e pagamento","title":"ISS: cálculo, vencimento e pagamento","description":"Base de cálculo, alíquota, apuração, vencimento e comprovação do recolhimento.","subtitle":"Apuração e recolhimento do imposto","icon":"calculator","originalTitle":"CÁLCULO, VENCIMENTO E PAGAMENTO DO ISS","sourcePage":41,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-112","sourceId":112,"title":"Como é feito o cálculo do ISS?","originalTitle":"Como é feito o cálculo do ISS?","sourcePage":41,"answer":"Na tributação sobre preço, o ISS é calculado pela aplicação da alíquota legal à base do serviço. Regimes de autônomos, sociedades ou Simples Nacional podem seguir tratamentos próprios, que devem ser conferidos antes da apuração.","review":false},{"id":"pergunta-113","sourceId":113,"title":"Qual é a alíquota a ser aplicada para o cálculo do ISS?","originalTitle":"Qual é a alíquota a ser aplicada para o cálculo do ISS?","sourcePage":41,"answer":"A alíquota depende do serviço, do enquadramento e da legislação vigente. Utilize o código e a tabela de Aracaju ou o tratamento do regime aplicável; não copie percentuais do guia de São Paulo.","review":true},{"id":"pergunta-114","sourceId":114,"title":"Qual é a base de cálculo do ISS?","originalTitle":"Qual é a base de cálculo do ISS?","sourcePage":41,"answer":"Em regra, a base é o preço do serviço, observadas as deduções e exceções legalmente admitidas. Desconto, material ou despesa só podem reduzir a base quando houver fundamento e documentação suficientes.","review":false},{"id":"pergunta-115","sourceId":115,"title":"Como é feito o cálculo do ISS se não houver preço do serviço?","originalTitle":"Como é feito o cálculo do ISS se não houver preço do serviço?","sourcePage":42,"answer":"Quando não houver preço conhecido ou a apuração ordinária não for possível, a legislação pode prever critérios de estimativa ou arbitramento. O cálculo não deve ser escolhido livremente pelo contribuinte; confirme o regime e a decisão aplicável.","review":true},{"id":"pergunta-116","sourceId":116,"title":"Em que casos o preço dos serviços poderá ser arbitrado pelas autoridades fiscais?","originalTitle":"Em que casos o preço dos serviços poderá ser arbitrado pelas autoridades fiscais?","sourcePage":42,"answer":"O arbitramento pode ser utilizado nas hipóteses legais em que os registros ou documentos não permitam apuração confiável. A autoridade deve observar procedimento, fundamentação e direito de defesa; solicite a memória do valor lançado.","review":false},{"id":"pergunta-117","sourceId":117,"title":"Qual é a data de vencimento do ISS?","originalTitle":"Qual é a data de vencimento do ISS?","sourcePage":42,"answer":"Confira o calendário de ISS divulgado pela SEMFAZ e o vencimento indicado na guia. Prestação, retenção e regime tributário podem envolver obrigações diferentes; não utilize uma data única do manual paulista.","review":true},{"id":"pergunta-118","sourceId":118,"title":"Por quanto tempo o contribuinte deve conservar os comprovantes de pagamento do ISS?","originalTitle":"Por quanto tempo o contribuinte deve conservar os comprovantes de pagamento do ISS?","sourcePage":43,"answer":"Guarde comprovantes e documentos fiscais pelo período exigido na legislação, considerando decadência, prescrição e eventuais processos. Se houver fiscalização ou discussão em andamento, preserve os documentos até a solução e a orientação correspondente.","review":true},{"id":"pergunta-119","sourceId":119,"title":"Como recolher o ISS sem inscrição municipal?","originalTitle":"Como deve proceder quem não tem CCM para recolher o ISS?","sourcePage":43,"answer":"A ausência de inscrição não dispensa o imposto quando ele for devido. Solicite orientação para regularizar o cadastro e emitir a guia adequada, informando serviço, período, CPF ou CNPJ e condição de prestador ou tomador.","review":false}]},{"number":11,"id":"capitulo-11","short":"ISS de obras e Habite-se","title":"ISS de obras e regularidade para o Habite-se","description":"Documentos da obra, apuração do ISS, deduções e análise de regularidade fiscal.","subtitle":"Construção, reforma e demolição","icon":"building","originalTitle":"CERTIFICADO DE QUITAÇÃO DO ISS PARA FINS DO HABITE-SE","sourcePage":44,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-121","sourceId":121,"title":"Como obter o certificado de quitação do ISS para fins do HABITE-SE?","originalTitle":"Como obter o certificado de quitação do ISS para fins do HABITE-SE?","sourcePage":44,"answer":"A regularidade do ISS da obra e a emissão do Habite-se envolvem competências fiscais e urbanísticas. Consulte a SEMFAZ sobre a quitação ou certidão exigida e o órgão urbanístico sobre o procedimento de conclusão da obra.","review":true},{"id":"pergunta-122","sourceId":122,"title":"Como é apurado o ISS devido pela construção, reforma ou demolição?","originalTitle":"Como é apurado o ISS devido pela construção, reforma ou demolição?","sourcePage":44,"answer":"A apuração considera os serviços de construção e as regras locais de preço, deduções e eventual arbitramento. Notas, contratos e comprovantes de recolhimento ajudam a demonstrar os serviços realizados; o valor não deve ser calculado pelas tabelas paulistas.","review":true},{"id":"pergunta-123","sourceId":123,"title":"Se houver deduções, como proceder para obter o certificado de quitação do ISS (HABITE-SE)?","originalTitle":"Se houver deduções, como proceder para obter o certificado de quitação do ISS (HABITE-SE)?","sourcePage":45,"answer":"Organize as notas, contratos e demais documentos que sustentem cada dedução legalmente admitida. Apresente-os no procedimento municipal; nem todo gasto com a obra constitui dedução do ISS.","review":true},{"id":"pergunta-124","sourceId":124,"title":"O que fará a unidade competente antes de fornecer o Certificado de Quitação do ISS para fins do HABITE-SE?","originalTitle":"O que fará a unidade competente antes de fornecer o Certificado de Quitação do ISS para fins do HABITE-SE?","sourcePage":45,"answer":"A análise fiscal pode conferir cadastro da obra, documentação dos serviços, cálculo, pagamentos e pendências. Eventuais exigências devem ser atendidas antes da emissão do documento de regularidade solicitado.","review":true},{"id":"pergunta-125","sourceId":125,"title":"Onde obter mais informações e protocolar o pedido do Certificado de Quitação do ISS para fins do HABITE-SE?","originalTitle":"Onde obter mais informações e protocolar o pedido do Certificado de Quitação do ISS para fins do HABITE-SE?","sourcePage":45,"answer":"Consulte o serviço fiscal correspondente na SEMFAZ e o licenciamento urbanístico municipal, disponível no SLIM quando aplicável. Identifique a obra e peça a relação exata de documentos e etapas exigidas em Aracaju.","review":true}]},{"number":12,"id":"capitulo-12","short":"Benefícios e regimes do ISS","title":"ISS: benefícios e regimes especiais","description":"Não incidência, imunidade, isenção, descontos e tratamentos especiais previstos em norma.","subtitle":"Enquadramentos e obrigações","icon":"shield","originalTitle":"DESCONTOS, NÃO-INCIDÊNCIA, IMUNIDADE, ISENÇÃO E REGIMES ESPECIAIS DO ISS","sourcePage":45,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"},{"label":"Benefícios fiscais — Transparência Aracaju","url":"https://transparencia.aracaju.se.gov.br/prefeitura/prestacao-de-contas/"}],"topics":[{"id":"pergunta-127","sourceId":127,"title":"Quais os casos em que não incide o ISS?","originalTitle":"Quais os casos em que não incide o ISS?","sourcePage":45,"answer":"A não incidência ocorre quando a operação não se enquadra na hipótese legal do imposto ou está abrangida por exclusão prevista em norma. Exportação de serviços, por exemplo, exige verificar as condições legais, e não apenas o endereço estrangeiro do contratante.","review":true},{"id":"pergunta-128","sourceId":128,"title":"Quem é imune do ISS?","originalTitle":"Quem é imune do ISS?","sourcePage":46,"answer":"A imunidade depende de proteção constitucional e do atendimento aos requisitos de cada pessoa e atividade. Mesmo quando não há imposto a recolher, podem existir obrigações cadastrais, de documentação e declaração.","review":true},{"id":"pergunta-129","sourceId":129,"title":"Quem é isento do ISS?","originalTitle":"Quem é isento do ISS?","sourcePage":46,"answer":"A isenção exige lei de Aracaju e atendimento às condições nela previstas. A página municipal de benefícios informa hipóteses de ISS; confirme a categoria, a vigência e a necessidade de requerimento antes de aplicar a dispensa.","review":true},{"id":"pergunta-130","sourceId":130,"title":"Onde solicitar informações sobre imunidade e isenção do ISS?","originalTitle":"Onde solicitar informações sobre imunidade e isenção do ISS","sourcePage":47,"answer":"Encaminhe à SEMFAZ a atividade exercida, o regime e o fundamento do benefício pretendido. Solicite orientação para reconhecimento e documentação, distinguindo imunidade constitucional de isenção concedida por lei municipal.","review":true},{"id":"pergunta-131","sourceId":131,"title":"Quem tem desconto do ISS?","originalTitle":"Quem tem desconto do ISS?","sourcePage":47,"answer":"Reduções e incentivos dependem do setor, da legislação e de eventuais requisitos de habilitação. Consulte a norma específica do benefício e confirme a aplicação ao serviço, ao período e ao contribuinte.","review":true},{"id":"pergunta-132","sourceId":132,"title":"O que são os regimes especiais para pagamento, escrituração e emissão de documentos do ISS?","originalTitle":"O que são os regimes especiais para pagamento, escrituração e emissão de documentos do ISS?","sourcePage":47,"answer":"Regime especial é um tratamento autorizado para cumprir obrigações de apuração, escrituração ou emissão fiscal em condições específicas. Não é uma escolha livre: exige base normativa e, quando previsto, autorização formal.","review":true},{"id":"pergunta-133","sourceId":133,"title":"Onde obter mais informações sobre regimes especiais?","originalTitle":"Onde obter mais informações sobre regimes especiais?","sourcePage":48,"answer":"Peça orientação à SEMFAZ descrevendo atividade, obrigação envolvida e motivo do tratamento solicitado. Até haver enquadramento ou autorização válida, cumpra as obrigações ordinárias aplicáveis ao seu caso.","review":true}]},{"number":13,"id":"capitulo-13","short":"Sociedades e autônomos","title":"ISS de sociedades de profissionais e autônomos","description":"Cadastro, enquadramento e obrigações de profissionais e sociedades.","subtitle":"Atividade profissional e regime tributário","icon":"users","originalTitle":"RECOLHIMENTO DO ISS PELAS SOCIEDADES DE PROFISSIONAIS E PELOS AUTÔNOMOS","sourcePage":48,"note":"Valores fixos, periodicidade e enquadramento de sociedades e autônomos dependem do regime vigente em Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-135","sourceId":135,"title":"O que são sociedades de profissionais?","originalTitle":"O que são sociedades de profissionais?","sourcePage":48,"answer":"São sociedades que reúnem profissionais para prestar determinados serviços, com características previstas no regime legal. Ter sócios da mesma profissão não basta, por si só, para assegurar tratamento tributário diferenciado.","review":true},{"id":"pergunta-136","sourceId":136,"title":"Quais sociedades se excluem do conceito de sociedade de profissionais?","originalTitle":"Quais sociedades se excluem do conceito de sociedade de profissionais?","sourcePage":48,"answer":"Características empresariais, composição, objeto, responsabilidade e forma de prestação podem afastar o regime, conforme a legislação aplicável. A análise deve considerar os atos societários e a atuação efetiva, e não apenas a razão social.","review":true},{"id":"pergunta-137","sourceId":137,"title":"Como é o cálculo do ISS devido pelas sociedades de profissionais?","originalTitle":"Como é o cálculo do ISS devido pelas sociedades de profissionais?","sourcePage":48,"answer":"O cálculo depende do enquadramento reconhecido e da regra municipal vigente. Pode haver tratamento próprio ou apuração sobre preço; confirme o regime em Aracaju antes de utilizar valores por profissional ou por período.","review":true},{"id":"pergunta-138","sourceId":138,"title":"Como verificar a atualização dos parâmetros de cálculo das sociedades de profissionais?","originalTitle":"Quando será atualizada a receita bruta mensal das sociedades de profissionais?","sourcePage":49,"answer":"A periodicidade e os critérios de atualização de valores ou parâmetros dependem da norma local. Os valores mensais e as regras de receita usados no guia paulista são referências históricas e não definem a apuração de Aracaju.","review":true},{"id":"pergunta-139","sourceId":139,"title":"Qual é o vencimento do ISS para as sociedades de profissionais?","originalTitle":"Qual é o vencimento do ISS para as sociedades de profissionais?","sourcePage":49,"answer":"Consulte o calendário municipal e o regime cadastrado para a sociedade. Confirme se o recolhimento é mensal ou segue periodicidade específica; não adote automaticamente o trimestre citado no manual de São Paulo.","review":true},{"id":"pergunta-140","sourceId":140,"title":"Quanto será o imposto no caso da sociedade de profissionais não exercer a prestação de serviços ou exercer somente em parte do período considerado?","originalTitle":"Quanto será o imposto no caso da sociedade de profissionais não exercer a prestação de serviços ou exercer somente em parte do período considerado?","sourcePage":50,"answer":"Inatividade ou exercício parcial precisam ser comprovados e analisados conforme o regime. A falta de receita não elimina necessariamente tributo fixo ou obrigação acessória; comunique a situação ao cadastro e confirme o tratamento fiscal.","review":true},{"id":"pergunta-141","sourceId":141,"title":"Como conferir o vencimento do ISS na baixa da sociedade de profissionais?","originalTitle":"Quando vence o imposto no caso de cancelamento no CCM da sociedade de profissionais?","sourcePage":50,"answer":"A baixa cadastral não encerra automaticamente débitos e declarações de períodos anteriores. Confirme os vencimentos finais e as obrigações até a data de encerramento reconhecida pelo município.","review":true},{"id":"pergunta-142","sourceId":142,"title":"Como conferir o primeiro vencimento do ISS no início da atividade?","originalTitle":"Quando vence o imposto no caso do início da atividade ocorrer no último mês do trimestre?","sourcePage":50,"answer":"A tributação no início da atividade depende da data de inscrição, do fato gerador e do regime local. Solicite orientação sobre o primeiro período e o respectivo vencimento, sem aplicar a regra trimestral paulista.","review":true},{"id":"pergunta-143","sourceId":143,"title":"Quando vence o imposto no caso da data fixada para pagamento coincidir com dia não-útil?","originalTitle":"Quando vence o imposto no caso da data fixada para pagamento coincidir com dia não-útil?","sourcePage":50,"answer":"A transferência de vencimento para dia útil depende da regra municipal e do calendário publicado. Confirme a data na guia atualizada; não presuma prorrogação sem previsão aplicável.","review":true},{"id":"pergunta-144","sourceId":144,"title":"Como é atualmente o regime de recolhimento do ISS pelos profissionais autônomos?","originalTitle":"Como é atualmente o regime de recolhimento do ISS pelos profissionais autônomos?","sourcePage":50,"answer":"O profissional autônomo deve verificar inscrição, atividade, regime de ISS e eventuais benefícios locais. O enquadramento pode ter regras próprias; o cadastro e as obrigações fiscais devem ser confirmados com a SEMFAZ.","review":true}]},{"number":14,"id":"capitulo-14","short":"Simples Nacional","title":"Simples Nacional","description":"Opção, elegibilidade, pendências, regularização e procedimentos de contestação.","subtitle":"Regime nacional e obrigações municipais","icon":"briefcase","originalTitle":"SIMPLES NACIONAL","sourcePage":50,"note":"","sources":[{"label":"Portal do Simples Nacional","url":"https://www8.receita.fazenda.gov.br/SimplesNacional/"},{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"}],"topics":[{"id":"pergunta-146","sourceId":146,"title":"O que é o Simples Nacional?","originalTitle":"O que é o Simples Nacional?","sourcePage":50,"answer":"O Simples Nacional é um regime previsto em legislação nacional para contribuintes elegíveis, com recolhimento de diversos tributos em documento unificado. A opção não elimina todas as obrigações municipais nem alcança automaticamente qualquer empresa.","review":false},{"id":"pergunta-147","sourceId":147,"title":"Quais os municípios que participam do Simples Nacional?","originalTitle":"Quais os municípios que participam do Simples Nacional?","sourcePage":51,"answer":"O regime tem abrangência nacional, incluindo as regras do ISS municipal. Ainda assim, cadastro, licenciamento, retenções e obrigações locais precisam ser observados em Aracaju.","review":false},{"id":"pergunta-148","sourceId":148,"title":"Quais os tributos incluídos no Simples Nacional?","originalTitle":"Quais os tributos incluídos no Simples Nacional?","sourcePage":51,"answer":"O documento unificado pode abranger IRPJ, IPI, CSLL, Cofins, PIS/Pasep, contribuição previdenciária patronal, ICMS e ISS, conforme a atividade e as exceções legais. Nem toda cobrança ou retenção fica incluída no DAS.","review":false},{"id":"pergunta-149","sourceId":149,"title":"Como aderir ao Simples Nacional?","originalTitle":"Como aderir ao Simples Nacional?","sourcePage":51,"answer":"A solicitação é feita no canal oficial do Simples Nacional e depende da elegibilidade e da regularização exigida. Confira o resultado e eventuais pendências, inclusive municipais, em vez de considerar a inscrição da empresa como opção automática.","review":false},{"id":"pergunta-150","sourceId":150,"title":"Quando deve ser feita a opção pelo Simples Nacional?","originalTitle":"Quando deve ser feita a opção pelo Simples Nacional?","sourcePage":51,"answer":"A janela de opção varia conforme a situação de empresa já em atividade ou em início de atividade e os atos vigentes. Consulte o calendário oficial no momento do pedido; os prazos apresentados no PDF de 2013 não devem ser utilizados.","review":true},{"id":"pergunta-151","sourceId":151,"title":"Quem pode aderir ao Simples Nacional?","originalTitle":"Quem pode aderir ao Simples Nacional?","sourcePage":51,"answer":"Podem optar contribuintes que atendam aos limites, atividades e demais condições da legislação nacional. Receita, participação societária, forma de constituição e situações impeditivas devem ser examinadas antes da solicitação.","review":false},{"id":"pergunta-152","sourceId":152,"title":"Quais os casos em que a opção pelo Simples Nacional não será deferida?","originalTitle":"Quais os casos em que a opção pelo Simples Nacional não será deferida?","sourcePage":51,"answer":"A opção pode ser indeferida por impedimento legal, pendência cadastral ou débito que impeça a entrada no regime. Consulte o termo e identifique qual órgão apontou a pendência para regularizar ou contestar corretamente.","review":false},{"id":"pergunta-153","sourceId":153,"title":"Quais as pendências junto à Prefeitura que impedem o contribuinte de aderir ao Simples Nacional?","originalTitle":"Quais as pendências junto à Prefeitura que impedem o contribuinte de aderir ao Simples Nacional?","sourcePage":52,"answer":"Pendências municipais relevantes podem envolver débitos exigíveis e inconsistências de cadastro previstas nas regras do regime. Solicite a identificação precisa da ocorrência à SEMFAZ; não conclua que qualquer processo em aberto é impeditivo.","review":false},{"id":"pergunta-154","sourceId":154,"title":"Quais os casos em que o optante do Simples Nacional será excluído do regime?","originalTitle":"Quais os casos em que o optante do Simples Nacional será excluído do regime?","sourcePage":52,"answer":"A exclusão pode decorrer de descumprimento de condições legais ou de situações previstas nos atos do regime. Leia o termo, seus efeitos e a data de ciência, pois os procedimentos variam conforme o motivo.","review":false},{"id":"pergunta-155","sourceId":155,"title":"Qual o prazo para regularizar os débitos tributários e permanecer no Simples Nacional?","originalTitle":"Qual o prazo para regularizar os débitos tributários e permanecer no Simples Nacional?","sourcePage":52,"answer":"O prazo deve ser conferido no termo recebido e na norma vigente. Regularização, parcelamento ou contestação só produzem os efeitos previstos para o caso; não use o prazo do manual paulista como referência atual.","review":true},{"id":"pergunta-156","sourceId":156,"title":"Onde o contribuinte poderá recorrer do não-deferimento da opção ou da exclusão do Simples Nacional?","originalTitle":"Onde o contribuinte poderá recorrer do não-deferimento da opção ou da exclusão do Simples Nacional?","sourcePage":52,"answer":"A impugnação deve ser dirigida ao órgão que emitiu o indeferimento ou a exclusão, seguindo o procedimento e o prazo do ato. Se a decisão for municipal, consulte o canal de processo fiscal da SEMFAZ.","review":false},{"id":"pergunta-157","sourceId":157,"title":"Como esclarecer dúvidas sobre a legislação do Simples Nacional?","originalTitle":"Como esclarecer dúvidas sobre a legislação do Simples Nacional?","sourcePage":52,"answer":"Consulte os manuais, perguntas e respostas e atos do Portal do Simples Nacional. Para cadastro, licenciamento ou débito municipal, complemente a consulta com a SEMFAZ de Aracaju.","review":false}]},{"number":15,"id":"capitulo-15","short":"Escrituração fiscal","title":"Escrituração e livros fiscais","description":"Registro de serviços, documentos, encerramento de competências e conservação das informações.","subtitle":"Registros e obrigações acessórias","icon":"book","originalTitle":"LIVRO FISCAL","sourcePage":53,"note":"O roteiro de livro fiscal físico de 2013 precisa ser compatibilizado com a escrituração e os sistemas atualmente exigidos em Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-159","sourceId":159,"title":"Qual é o livro fiscal em vigor e para que serve?","originalTitle":"Qual é o livro fiscal em vigor e para que serve?","sourcePage":53,"answer":"A escrituração fiscal registra serviços, documentos e apuração do imposto. Em Aracaju, a forma exigida deve ser conferida no sistema e na regulamentação vigentes; o livro físico mencionado no PDF não deve ser presumido como obrigação atual.","review":true},{"id":"pergunta-160","sourceId":160,"title":"Como utilizar o livro fiscal?","originalTitle":"Como utilizar o livro fiscal?","sourcePage":53,"answer":"Registre as operações com seus documentos, competência, valores e tratamento tributário, na forma exigida. Confira os dados antes de transmitir ou encerrar a declaração e guarde o comprovante de entrega.","review":true},{"id":"pergunta-161","sourceId":161,"title":"Qual o prazo para escriturar e encerrar o livro fiscal?","originalTitle":"Qual o prazo para escriturar e encerrar o livro fiscal?","sourcePage":53,"answer":"O prazo de escrituração e encerramento deve ser verificado na obrigação específica e no calendário municipal. Emissão de nota, declaração e pagamento são etapas distintas e podem ter datas diferentes.","review":true},{"id":"pergunta-162","sourceId":162,"title":"O que deve ser feito no caso de extravio ou danificação de livro fiscal?","originalTitle":"O que deve ser feito no caso de extravio ou danificação de livro fiscal?","sourcePage":54,"answer":"Preserve as informações disponíveis e comunique o ocorrido pelo procedimento legal aplicável. Solicite orientação sobre reconstituição dos registros e recuperação de arquivos; extravio não dispensa comprovação das operações.","review":false},{"id":"pergunta-163","sourceId":163,"title":"Como proceder com os livros fiscais no caso de reativação do cadastro mobiliário?","originalTitle":"Como proceder com os livros fiscais no caso de reativação do CCM?","sourcePage":54,"answer":"Na reativação, verifique quais períodos e registros devem ser regularizados e a forma atual de escrituração. Não reabra livros ou omita competências seguindo apenas o procedimento histórico de São Paulo.","review":true}]},{"number":16,"id":"capitulo-16","short":"Nota fiscal de serviços","title":"Nota Fiscal de Serviços Eletrônica","description":"Emissão, consulta, autenticidade, RPS e recolhimento relacionado à NFS-e.","subtitle":"Documentação eletrônica dos serviços","icon":"receipt","originalTitle":"NOTA FISCAL DE SERVIÇOS ELETRÔNICA– NFS-e","sourcePage":54,"note":"Confirme o emissor aplicável ao seu regime e as regras atuais de transição. Créditos de NFS-e para abatimento do IPTU dependem de programa municipal específico, não confirmado nesta versão.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Portal nacional da NFS-e","url":"https://www.gov.br/nfse/pt-br"},{"label":"NFS-e para MEI — orientações oficiais","url":"https://www.gov.br/empresas-e-negocios/pt-br/empreendedor/servicos-para-mei/nota-fiscal/nota-fiscal-de-servico-eletronica-nfs-e"}],"topics":[{"id":"pergunta-165","sourceId":165,"title":"O que é a Nota Fiscal de Serviços Eletrônica – NFS-e?","originalTitle":"O que é a Nota Fiscal de Serviços Eletrônica – NFS-e?","sourcePage":54,"answer":"A NFS-e é o documento eletrônico que registra a prestação de serviço. Sua emissão, autenticidade, cancelamento e tratamento do ISS seguem o sistema e a regulamentação aplicáveis ao contribuinte.","review":false},{"id":"pergunta-166","sourceId":166,"title":"Qual a diferença entre a NFS-e e os documentos de mercadorias ou programas estaduais?","originalTitle":"Qual a diferença entre a Nota Fiscal de Serviços Eletrônica – NFS-e e a Nota Fiscal Paulista – NFP?","sourcePage":55,"answer":"A NFS-e documenta serviços e se relaciona ao ISS. Documentos de venda de mercadorias e programas estaduais de incentivo ao consumidor têm outra finalidade; a Nota Fiscal Paulista citada no PDF é um programa de São Paulo.","review":false},{"id":"pergunta-167","sourceId":167,"title":"Como funciona a Nota Fiscal Eletrônica?","originalTitle":"Como funciona a Nota Fiscal Eletrônica?","sourcePage":55,"answer":"O prestador informa a operação no emissor autorizado, que gera o documento com identificação e dados para consulta. O tomador pode conferir a autenticidade e os valores; emitir a nota não significa necessariamente que o imposto já foi pago.","review":false},{"id":"pergunta-168","sourceId":168,"title":"Quem está obrigado a emitir a Nota Fiscal Eletrônica?","originalTitle":"Quem está obrigado a emitir a Nota Fiscal Eletrônica?","sourcePage":56,"answer":"A obrigação depende da atividade, do regime e da regulamentação vigente. Confira o cadastro e as orientações atuais da SEMFAZ ou do emissor nacional aplicável, especialmente para MEI e contribuintes abrangidos por mudanças de sistema.","review":true},{"id":"pergunta-169","sourceId":169,"title":"Em caso de início de atividade, como verificar se há obrigatoriedade de emitir Nota Fiscal de Serviços Eletrônica?","originalTitle":"Em caso de início de atividade, como verificar se há obrigatoriedade de emitir Nota Fiscal de Serviços Eletrônica?","sourcePage":56,"answer":"Antes de prestar os serviços, confira sua inscrição, atividade, regime e habilitação no emissor. Peça orientação se houver dúvida sobre dispensa ou obrigatoriedade; começar a atividade não autoriza emitir documentos por sistema inadequado.","review":true},{"id":"pergunta-170","sourceId":170,"title":"Como emitir a Nota Fiscal de Serviços Eletrônica?","originalTitle":"Como emitir a Nota Fiscal de Serviços Eletrônica?","sourcePage":56,"answer":"Acesse o emissor indicado para seu regime, identifique prestador e tomador e informe serviço, valores e tributação. Confira os dados antes de confirmar a emissão e disponibilize o documento ao tomador; MEI deve consultar o canal nacional próprio.","review":true},{"id":"pergunta-171","sourceId":171,"title":"Quando começa a vigorar a opção pela emissão da Nota Fiscal de Serviços Eletrônica?","originalTitle":"Quando começa a vigorar a opção pela emissão da Nota Fiscal de Serviços Eletrônica?","sourcePage":56,"answer":"A data de início da emissão obrigatória ou facultativa depende do enquadramento e do ato vigente. Confirme a autorização no sistema e as regras de transição, sem aplicar o período de opção descrito no guia de 2013.","review":true},{"id":"pergunta-172","sourceId":172,"title":"Como fica a situação dos contribuintes que possuem regime especial de recolhimento do ISS (individual ou coletivo)?","originalTitle":"Como fica a situação dos contribuintes que possuem regime especial de recolhimento do ISS (individual ou coletivo)?","sourcePage":57,"answer":"A existência de regime especial não permite concluir automaticamente que o contribuinte está dispensado da NFS-e. Confira o ato de autorização e as obrigações que permanecem aplicáveis, inclusive em mudanças de emissor.","review":true},{"id":"pergunta-173","sourceId":173,"title":"Como fica a situação das entidades imunes do ISS?","originalTitle":"Como fica a situação das entidades imunes do ISS?","sourcePage":57,"answer":"Imunidade pode afastar o imposto em situações próprias, mas não elimina necessariamente a emissão de documento ou a declaração. Identifique corretamente o tratamento na nota e siga as obrigações previstas para a entidade.","review":true},{"id":"pergunta-174","sourceId":174,"title":"O que é o Recibo Provisório de Serviços (RPS)?","originalTitle":"O que é o Recibo Provisório de Serviços (RPS)?","sourcePage":57,"answer":"O RPS é um recibo provisório utilizado nas condições autorizadas para posterior conversão em NFS-e. Ele não deve substituir permanentemente a nota nem ser utilizado fora das hipóteses admitidas pelo sistema competente.","review":false},{"id":"pergunta-175","sourceId":175,"title":"Como gerar o RPS?","originalTitle":"Como gerar o RPS?","sourcePage":57,"answer":"A emissão e a numeração do RPS devem seguir a autorização e o padrão aceitos no sistema aplicável. Organize os dados e controle as conversões para evitar duplicidade, falta de nota ou perda de prazo.","review":true},{"id":"pergunta-176","sourceId":176,"title":"Qual o prazo para substituir o RPS ou a nota fiscal convencional por NFS-e?","originalTitle":"Qual o prazo para substituir o RPS ou a nota fiscal convencional por NFS-e?","sourcePage":57,"answer":"Confirme o prazo de conversão na regulamentação e no emissor vigentes. Não utilize o prazo paulista de 2013; em transições para outro sistema, verifique também o documento provisório e o procedimento aceitos.","review":true},{"id":"pergunta-177","sourceId":177,"title":"Quais os benefícios para quem emite a Nota Fiscal de Serviços Eletrônica?","originalTitle":"Quais os benefícios para quem emite a Nota Fiscal de Serviços Eletrônica?","sourcePage":58,"answer":"A emissão eletrônica facilita organização, consulta, comprovação dos serviços e integração dos registros. Esses benefícios não dispensam a conferência dos dados, o cumprimento das declarações e o recolhimento do imposto quando devido.","review":false},{"id":"pergunta-178","sourceId":178,"title":"Quais os benefícios para quem recebe a Nota Fiscal de Serviços Eletrônica?","originalTitle":"Quais os benefícios para quem recebe a Nota Fiscal de Serviços Eletrônica?","sourcePage":58,"answer":"O tomador recebe um documento verificável, com informações da contratação e valores. Guarde a nota e confira sua autenticidade; desconto, crédito ou sorteio só existem quando instituídos por programa aplicável.","review":false},{"id":"pergunta-179","sourceId":179,"title":"Como recolher o ISS referente às Notas Fiscais de Serviços Eletrônicas?","originalTitle":"Como recolher o ISS referente às Notas Fiscais de Serviços Eletrônicas?","sourcePage":58,"answer":"O recolhimento deve observar quem é responsável pelo imposto e o regime da operação. Confira a competência e a forma de guia ou documento unificado antes de pagar, evitando duplicar ISS já tratado em retenção ou regime específico.","review":false},{"id":"pergunta-180","sourceId":180,"title":"Quem está dispensado de emitir a guia de recolhimento pelo sistema da NFS-e?","originalTitle":"Quem está dispensado de emitir a guia de recolhimento pelo sistema da NFS-e?","sourcePage":59,"answer":"A forma de recolhimento pode ser diferente para Simples Nacional, MEI, retenções e outras situações legalmente previstas. Verifique se deve haver DAM municipal, DAS ou outro procedimento; a emissão da NFS-e não define sozinha o documento de pagamento.","review":true},{"id":"pergunta-181","sourceId":181,"title":"Qual é a data de vencimento do ISS referente às Notas Fiscais Eletrônicas?","originalTitle":"Qual é a data de vencimento do ISS referente às Notas Fiscais Eletrônicas?","sourcePage":59,"answer":"O vencimento segue o calendário e o regime aplicáveis ao ISS daquela operação. A data da emissão da nota e a competência do serviço devem ser conferidas para evitar usar um vencimento de obrigação diferente.","review":true},{"id":"pergunta-182","sourceId":182,"title":"Como verificar a autenticidade de uma NFS-e?","originalTitle":"Como verificar a autenticidade de uma NFS-e?","sourcePage":59,"answer":"Use a consulta de autenticidade do emissor indicado na nota e confira número, código de verificação, prestador, tomador e valores. Uma imagem ou arquivo recebido isoladamente não substitui a verificação no canal oficial.","review":false},{"id":"pergunta-183","sourceId":183,"title":"Como saber se um estabelecimento deve emitir NFS-e?","originalTitle":"Como saber se um estabelecimento deve a emitir a Nota Fiscal Eletrônica?","sourcePage":59,"answer":"Verifique a atividade, o regime e a habilitação do estabelecimento no sistema competente. Se precisar de confirmação oficial de obrigatoriedade, consulte a SEMFAZ com os dados do prestador e do serviço.","review":false},{"id":"pergunta-184","sourceId":184,"title":"Como denunciar um estabelecimento que não emite Nota Fiscal Eletrônica?","originalTitle":"Como denunciar um estabelecimento que não emite Nota Fiscal Eletrônica?","sourcePage":60,"answer":"Registre a ocorrência no canal oficial de atendimento ou denúncia, informando prestador, data, serviço e documentos disponíveis. Antes disso, confira se a obrigação se aplica à operação e ao regime envolvido.","review":false},{"id":"pergunta-185","sourceId":185,"title":"Há créditos de NFS-e para utilização pelo tomador em Aracaju?","originalTitle":"Como o tomador de serviços poderá consultar e utilizar o valor dos créditos gerados pelas Notas Fiscais Eletrônicas?","sourcePage":60,"answer":"O crédito para abatimento de IPTU descrito no manual depende de programa específico de São Paulo. Para Aracaju, a existência, o funcionamento e o canal de utilização de programa equivalente precisam de confirmação municipal.","review":true},{"id":"pergunta-186","sourceId":186,"title":"Como verificar quem pode receber créditos de um programa de NFS-e?","originalTitle":"Quais os tomadores de serviços que não farão jus aos créditos gerados pelas Notas Fiscais Eletrônicas?","sourcePage":60,"answer":"As exclusões de beneficiários dependem da lei de um programa efetivamente instituído. Sem confirmação de programa local de créditos da NFS-e, não é possível aplicar a relação de tomadores excluídos do guia paulista.","review":true},{"id":"pergunta-187","sourceId":187,"title":"É possível indicar um imóvel para abatimento de IPTU com créditos de NFS-e?","originalTitle":"Quais imóveis podem ser indicados para ter abatimento do IPTU?","sourcePage":60,"answer":"A vinculação de imóvel ao abatimento só é possível se houver programa municipal com essa previsão. A elegibilidade e a indicação da inscrição devem seguir a regra local, sem aproveitar automaticamente os critérios de São Paulo.","review":true},{"id":"pergunta-188","sourceId":188,"title":"Como conferir a validade de créditos de um programa de NFS-e?","originalTitle":"Qual é a validade dos créditos gerados pelas Notas Fiscais Eletrônicas?","sourcePage":61,"answer":"A validade de créditos e as datas de utilização dependem do programa que os instituiu. Este guia não atribui prazo a créditos da NFS-e em Aracaju sem confirmação de legislação e serviço municipal correspondentes.","review":true}]},{"number":17,"id":"capitulo-17","short":"Instituições financeiras","title":"Declarações de instituições financeiras","description":"Enquadramento, sistema de declaração e calendário das obrigações específicas.","subtitle":"Declarações e obrigações setoriais","icon":"building","originalTitle":"DECLARAÇÃO DE INSTITUIÇÕES FINANCEIRAS - DIF","sourcePage":61,"note":"A obrigação de declaração de instituições financeiras e sua denominação precisam de confirmação local. A DIF paulista não foi apresentada como obrigação de Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-190","sourceId":190,"title":"O que é a declaração fiscal de instituições financeiras?","originalTitle":"O que é a declaração de instituições financeiras (DIF)?","sourcePage":61,"answer":"O tópico paulista trata de declaração específica de instituições financeiras. Para Aracaju, deve-se confirmar qual declaração ou sistema é exigido dessas instituições e seu regulamento; a denominação DIF não deve ser presumida como obrigação local.","review":true},{"id":"pergunta-191","sourceId":191,"title":"Quem deve apresentar declaração de instituição financeira?","originalTitle":"Quem é obrigado a apresentar a DIF?","sourcePage":61,"answer":"A obrigação alcança os contribuintes e situações definidos na regulamentação aplicável às instituições financeiras. A SEMFAZ deve confirmar o sistema vigente e o enquadramento da instituição antes da orientação de entrega.","review":true},{"id":"pergunta-192","sourceId":192,"title":"Como conferir os prazos da declaração de instituição financeira?","originalTitle":"Quais são os prazos de entrega da DIF?","sourcePage":62,"answer":"Os prazos devem ser consultados na obrigação local e no calendário correspondente. Não utilize as datas da DIF paulista; verifique competência, forma de transmissão e comprovante de recebimento exigidos em Aracaju.","review":true}]},{"number":18,"id":"capitulo-18","short":"Taxas de estabelecimentos","title":"Estabelecimentos: licenciamento e taxas","description":"Atividade, cadastro, lançamento e pagamento de taxas municipais relacionadas ao estabelecimento.","subtitle":"Fiscalização e licenciamento de atividades","icon":"store","originalTitle":"TAXA DE FISCALIZAÇÃO DE ESTABELECIMENTO - TFE","sourcePage":62,"note":"O portal de Aracaju identifica a TLF. A sigla TFE do guia paulista não foi tratada como nome ou regime automaticamente equivalente.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-194","sourceId":194,"title":"O que são as taxas de fiscalização e licenciamento de estabelecimentos?","originalTitle":"O que é a TFE?","sourcePage":62,"answer":"A TFE é o nome usado no guia de São Paulo para uma taxa de fiscalização de estabelecimentos. Em Aracaju, o portal municipal identifica a TLF; confirme o nome completo, a incidência e a lei do lançamento local antes de tratar as duas taxas como equivalentes.","review":true},{"id":"pergunta-195","sourceId":195,"title":"Qual o fato gerador da taxa de estabelecimentos?","originalTitle":"Qual o fato gerador da TFE?","sourcePage":62,"answer":"Uma taxa de fiscalização pode decorrer do exercício regular do poder de polícia sobre determinada atividade. O fato gerador concreto da cobrança de Aracaju precisa ser identificado no Código Tributário e no documento de lançamento.","review":true},{"id":"pergunta-196","sourceId":196,"title":"O que é considerado estabelecimento para fins de fiscalização e licenciamento?","originalTitle":"O que é estabelecimento para fins da TFE?","sourcePage":62,"answer":"O conceito fiscal de estabelecimento depende da norma aplicável e pode considerar o local onde a atividade é exercida. Ter ou não placa, atendimento ao público ou nome comercial não resolve isoladamente o enquadramento.","review":true},{"id":"pergunta-197","sourceId":197,"title":"O nome comercial altera o enquadramento do estabelecimento?","originalTitle":"Qual a importância do nome do estabelecimento para fins da TFE?","sourcePage":63,"answer":"O nome comercial não é o único critério para reconhecer um estabelecimento ou uma atividade tributável. Confira a identificação cadastral, o endereço e a atividade efetiva para evitar confundir mudança de nome com abertura ou encerramento.","review":true},{"id":"pergunta-198","sourceId":198,"title":"Quem é o sujeito passivo da taxa de estabelecimentos?","originalTitle":"Quem é o sujeito passivo da TFE?","sourcePage":63,"answer":"O sujeito passivo é a pessoa indicada pela lei como contribuinte ou responsável pela taxa. Verifique o cadastro e o lançamento local, especialmente em alterações, compartilhamento de endereço e exercício de múltiplas atividades.","review":true},{"id":"pergunta-199","sourceId":199,"title":"Quem deve lançar a taxa de estabelecimentos?","originalTitle":"Quem deve lançar a TFE?","sourcePage":63,"answer":"A forma de lançamento deve seguir a legislação municipal e o serviço correspondente. Confira se o valor é lançado pela administração ou depende de declaração, sem aplicar a sistemática de lançamento da TFE paulista.","review":true},{"id":"pergunta-200","sourceId":200,"title":"Como é calculada a taxa de estabelecimentos?","originalTitle":"Como é calculada a TFE?","sourcePage":64,"answer":"O cálculo deve utilizar a tabela municipal vigente e os critérios definidos para a atividade. Valores, faixas e parâmetros paulistanos não são referências para a guia de Aracaju.","review":true},{"id":"pergunta-201","sourceId":201,"title":"Como são classificadas as atividades para fins da taxa?","originalTitle":"Quais os conceitos de atividades para fins da TFE?","sourcePage":64,"answer":"O enquadramento considera as atividades e os critérios previstos na tabela e no cadastro municipais. Atualize a atividade efetivamente exercida e confirme o código utilizado no lançamento.","review":true},{"id":"pergunta-202","sourceId":202,"title":"Quando ocorre a incidência da taxa de estabelecimentos?","originalTitle":"Quando ocorre o fato gerador e incide a TFE?","sourcePage":64,"answer":"A ocorrência do fato gerador e a periodicidade dependem da lei da taxa em Aracaju. Início, continuidade, mudança ou encerramento da atividade devem ser analisados no procedimento local, sem presumir a mesma regra de São Paulo.","review":true},{"id":"pergunta-203","sourceId":203,"title":"Como e quando recolher a taxa de estabelecimentos de incidência anual?","originalTitle":"Como e quando recolher a TFE de incidência anual?","sourcePage":65,"answer":"Para cobrança anual prevista no lançamento local, confira o calendário de TLF e a guia do exercício. Confirme as condições de pagamento e se há necessidade de atualizar o cadastro antes da emissão.","review":true},{"id":"pergunta-204","sourceId":204,"title":"Como e quando recolher a taxa de estabelecimentos de incidência mensal?","originalTitle":"Como e quando recolher a TFE de incidência mensal?","sourcePage":65,"answer":"A existência de incidência mensal precisa de fundamento na legislação local. Se a guia indicar essa periodicidade, confirme com a SEMFAZ o período e o vencimento; o modelo mensal paulista não deve ser importado.","review":true},{"id":"pergunta-205","sourceId":205,"title":"Como e quando recolher a taxa de estabelecimentos de incidência diária ou por evento?","originalTitle":"Como e quando recolher a TFE de incidência diária ou por evento?","sourcePage":65,"answer":"Atividades temporárias e eventos podem envolver licenças e taxas próprias. Consulte o órgão de licenciamento e a SEMFAZ sobre a cobrança aplicável ao evento, seu período e o responsável pelo pagamento.","review":true},{"id":"pergunta-206","sourceId":206,"title":"Como emitir a 2ª via da guia de pagamento da taxa de estabelecimentos?","originalTitle":"Como emitir a 2ª via da guia de pagamento da TFE?","sourcePage":66,"answer":"Solicite emissão ou atualização da guia da taxa efetivamente lançada em Aracaju, identificando inscrição, receita e exercício. Não procure uma guia de TFE paulista para quitar obrigação municipal local.","review":true},{"id":"pergunta-207","sourceId":207,"title":"O que mais deve ser observado sobre o recolhimento da taxa de estabelecimentos?","originalTitle":"O que mais deve ser observado sobre o recolhimento da TFE?","sourcePage":66,"answer":"Confira receita, contribuinte, atividade, período e vencimento e guarde o comprovante. O pagamento da taxa não deve ser confundido com a concessão ou renovação automática do alvará e das demais licenças.","review":true},{"id":"pergunta-208","sourceId":208,"title":"Quem está isento do pagamento da taxa de estabelecimentos?","originalTitle":"Quem está isento do pagamento da TFE?","sourcePage":66,"answer":"A isenção depende de previsão municipal e de enquadramento comprovado. Aracaju publica hipóteses de isenção de TLF; confirme a categoria e os requisitos antes de considerar a taxa dispensada.","review":true},{"id":"pergunta-209","sourceId":209,"title":"Onde solicitar informações e requerimentos sobre isenções da taxa de estabelecimentos?","originalTitle":"Onde solicitar informações e requerimentos sobre isenções da TFE?","sourcePage":66,"answer":"Solicite à SEMFAZ informação sobre o benefício relacionado à taxa local, indicando atividade e fundamento pretendido. Verifique se o reconhecimento exige requerimento e quais documentos devem acompanhá-lo.","review":true},{"id":"pergunta-210","sourceId":210,"title":"Quem não está sujeito à incidência da taxa de estabelecimentos?","originalTitle":"Quem não está sujeito à incidência da TFE?","sourcePage":66,"answer":"Não incidência e isenção são situações distintas. A primeira depende de a atividade estar fora da hipótese da taxa; a segunda exige benefício legal para uma situação que seria tributável.","review":true},{"id":"pergunta-211","sourceId":211,"title":"Como tirar outras dúvidas sobre taxa de estabelecimentos?","originalTitle":"Como tirar outras dúvidas sobre TFE?","sourcePage":67,"answer":"Reúna inscrição municipal, atividade, guia e exercício. Consulte a SEMFAZ sobre a cobrança e o SLIM sobre o licenciamento, conforme a natureza da sua dúvida.","review":true}]},{"number":19,"id":"capitulo-19","short":"Publicidade e anúncios","title":"Publicidade: licenciamento e taxas","description":"Características do anúncio, autorização, eventual cobrança e hipóteses de dispensa.","subtitle":"Instalação e uso de publicidade","icon":"megaphone","originalTitle":"TAXA DE FISCALIZAÇÃO DE ANÚNCIOS - TFA","sourcePage":67,"note":"A denominação, a tabela e as hipóteses de cobrança por publicidade precisam de confirmação no licenciamento e na legislação de Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-213","sourceId":213,"title":"O que é a cobrança relacionada à fiscalização de anúncios?","originalTitle":"O que é a TFA?","sourcePage":67,"answer":"O guia paulista chama de TFA a taxa de fiscalização de anúncios. A denominação, a existência e a incidência de cobrança equivalente em Aracaju devem ser confirmadas na legislação e no licenciamento de publicidade locais.","review":true},{"id":"pergunta-214","sourceId":214,"title":"O que são anúncios para efeito da taxa relacionada à publicidade?","originalTitle":"O que são anúncios para efeito da TFA?","sourcePage":67,"answer":"Publicidade pode abranger placas, painéis e outros meios de divulgação, conforme a classificação legal. Antes de instalar ou alterar uma peça, confira as condições e eventuais dispensas do licenciamento municipal.","review":true},{"id":"pergunta-215","sourceId":215,"title":"Quem é o sujeito passivo da taxa relacionada à publicidade?","originalTitle":"Quem é o sujeito passivo da TFA?","sourcePage":67,"answer":"A lei deve identificar quem responde pela cobrança relacionada ao anúncio. Proprietário do imóvel, anunciante e responsável pela instalação podem ter papéis diferentes; confirme o enquadramento no procedimento local.","review":true},{"id":"pergunta-216","sourceId":216,"title":"Como é calculada a taxa relacionada à publicidade?","originalTitle":"Como é calculada a TFA?","sourcePage":68,"answer":"O cálculo depende da tabela e dos critérios locais, que podem considerar tipo, dimensão, localização ou período. Nenhum valor da TFA paulista deve ser aplicado automaticamente em Aracaju.","review":true},{"id":"pergunta-217","sourceId":217,"title":"Quem deve calcular a taxa relacionada à publicidade?","originalTitle":"Quem deve calcular a TFA?","sourcePage":68,"answer":"A responsabilidade por declarar dados e a forma de lançamento devem ser confirmadas no serviço municipal. Informe corretamente as características da publicidade e confira o documento emitido pelo órgão competente.","review":true},{"id":"pergunta-218","sourceId":218,"title":"Quando ocorre o fato gerador e incide a taxa relacionada à publicidade?","originalTitle":"Quando ocorre o fato gerador e incide a TFA?","sourcePage":69,"answer":"A incidência deve ser verificada na norma de Aracaju, considerando a instalação e a utilização do anúncio. A data e o período de cobrança não devem ser deduzidos do calendário paulista.","review":true},{"id":"pergunta-219","sourceId":219,"title":"Quais os casos que não afastam a incidência e o pagamento da taxa relacionada à publicidade?","originalTitle":"Quais os casos que não afastam a incidência e o pagamento da TFA?","sourcePage":69,"answer":"Pagamento, licença e regularidade urbanística são questões relacionadas, mas distintas. A ausência de autorização não necessariamente elimina obrigação fiscal; confirme os efeitos na legislação local e regularize a publicidade.","review":true},{"id":"pergunta-220","sourceId":220,"title":"Como e quando recolher a taxa relacionada à publicidade de incidência anual?","originalTitle":"Como e quando recolher a TFA de incidência anual?","sourcePage":69,"answer":"Só utilize pagamento anual se essa for a periodicidade da cobrança local. Confira o documento, o calendário e as condições do licenciamento correspondentes ao anúncio.","review":true},{"id":"pergunta-221","sourceId":221,"title":"Como e quando recolher a taxa relacionada à publicidade de incidência mensal?","originalTitle":"Como e quando recolher a TFA de incidência mensal?","sourcePage":70,"answer":"Cobrança mensal exige previsão municipal específica. Verifique receita, período e vencimento antes de pagar; a incidência mensal prevista no PDF não demonstra obrigação equivalente em Aracaju.","review":true},{"id":"pergunta-222","sourceId":222,"title":"Como e quando recolher a taxa relacionada à publicidade de incidência por evento?","originalTitle":"Como e quando recolher a TFA de incidência por evento?","sourcePage":70,"answer":"Publicidade temporária ou vinculada a evento deve seguir o procedimento municipal aplicável. Informe duração, local e características ao órgão competente para verificar licença, taxa e vencimento.","review":true},{"id":"pergunta-223","sourceId":223,"title":"Como emitir a 2ª via da guia de pagamento da taxa relacionada à publicidade?","originalTitle":"Como emitir a 2ª via da guia de pagamento da TFA?","sourcePage":70,"answer":"Solicite a guia da receita efetivamente lançada para publicidade, usando os dados do anúncio ou da inscrição. Se não houver emissão eletrônica identificável, consulte o atendimento municipal competente.","review":true},{"id":"pergunta-224","sourceId":224,"title":"O que mais deve ser observado sobre o recolhimento da taxa relacionada à publicidade?","originalTitle":"O que mais deve ser observado sobre o recolhimento da TFA?","sourcePage":70,"answer":"Confira se a guia corresponde ao anúncio e ao período corretos. A quitação não substitui a autorização de instalação ou o cumprimento das regras de publicidade e uso do espaço.","review":true},{"id":"pergunta-225","sourceId":225,"title":"Quais anúncios não estão sujeitos à incidência da taxa relacionada à publicidade?","originalTitle":"Quais anúncios não estão sujeitos à incidência da TFA?","sourcePage":70,"answer":"Anúncios dispensados ou não tributáveis precisam ser identificados na legislação local. Dimensão reduzida, finalidade institucional ou falta de remuneração não asseguram, por si só, dispensa de taxa e licença.","review":true},{"id":"pergunta-226","sourceId":226,"title":"Onde requerer da isenção da taxa relacionada à publicidade e obter outras informações sobre não-incidência e isenções?","originalTitle":"Onde requerer da isenção da TFA e obter outras informações sobre não-incidência e isenções?","sourcePage":72,"answer":"Verifique primeiro se a hipótese é isenção, não incidência ou dispensa de licenciamento. Solicite análise ao órgão responsável pela publicidade e à SEMFAZ quando a questão envolver a taxa.","review":true},{"id":"pergunta-227","sourceId":227,"title":"Como tirar outras dúvidas sobre taxa relacionada à publicidade?","originalTitle":"Como tirar outras dúvidas sobre TFA?","sourcePage":72,"answer":"Descreva o anúncio, o endereço, as dimensões, a finalidade e o período. Esses dados permitem direcionar a consulta ao licenciamento e, se houver cobrança, à administração tributária municipal.","review":true}]},{"number":20,"id":"capitulo-20","short":"Resíduos de saúde","title":"Resíduos de serviços de saúde","description":"Classificação, responsabilidades e análise de eventual cobrança municipal relacionada aos resíduos.","subtitle":"Resíduos e responsabilidades do estabelecimento","icon":"health","originalTitle":"TAXA DE RESÍDUOS SÓLIDOS DE SERVIÇOS DE SAÚDE - TRSS","sourcePage":72,"note":"A existência de uma taxa municipal equivalente à TRSS de São Paulo não foi confirmada. Obrigações de gerenciamento de resíduos devem ser distinguidas de cobranças tributárias.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-229","sourceId":229,"title":"Existe taxa municipal relacionada aos resíduos de serviços de saúde?","originalTitle":"O que é a TRSS?","sourcePage":72,"answer":"A TRSS citada no PDF é uma cobrança de São Paulo relacionada a resíduos de serviços de saúde. Não se deve afirmar que existe em Aracaju com o mesmo nome ou as mesmas condições sem confirmar a legislação local.","review":true},{"id":"pergunta-230","sourceId":230,"title":"O que são resíduos de serviços de saúde?","originalTitle":"O que são resíduos sólidos para fins da TRSS?","sourcePage":72,"answer":"Resíduos de serviços de saúde exigem classificação e manejo próprios conforme sua natureza e risco. A definição sanitária e ambiental não significa, por si só, que exista uma taxa municipal com os parâmetros do guia paulista.","review":true},{"id":"pergunta-231","sourceId":231,"title":"Como verificar o fato gerador de eventual taxa sobre resíduos de saúde?","originalTitle":"Qual o fato gerador da TRSS?","sourcePage":73,"answer":"Um tributo depende de hipótese de incidência prevista em lei. A prestação ou disponibilidade de serviço e a classificação do resíduo devem ser examinadas na norma local antes de orientar qualquer cobrança.","review":true},{"id":"pergunta-232","sourceId":232,"title":"Quem é o sujeito passivo da eventual taxa sobre resíduos de saúde?","originalTitle":"Quem é o sujeito passivo da TRSS?","sourcePage":73,"answer":"A pessoa responsável por gerenciar os resíduos e o sujeito passivo de eventual taxa devem ser identificados nas normas aplicáveis. Uma obrigação sanitária ou contratual não permite presumir automaticamente a responsabilidade tributária.","review":true},{"id":"pergunta-233","sourceId":233,"title":"O que é estabelecimento gerador de resíduos sólidos para fins da eventual taxa sobre resíduos de saúde?","originalTitle":"O que é estabelecimento gerador de resíduos sólidos para fins da TRSS?","sourcePage":73,"answer":"Serviços de saúde e atividades relacionadas podem gerar resíduos sujeitos a gerenciamento específico. A classificação do estabelecimento deve ser confirmada pelos órgãos sanitário e ambiental e, para eventual cobrança, pela legislação tributária.","review":true},{"id":"pergunta-234","sourceId":234,"title":"Como verificar o cálculo de eventual taxa sobre resíduos de saúde?","originalTitle":"Como é calculada a TRSS?","sourcePage":73,"answer":"Não há valor ou fórmula local confirmados nesta versão para uma taxa equivalente à TRSS. Consulte a SEMFAZ e os órgãos responsáveis sobre a existência da receita e seus critérios antes de calcular ou pagar.","review":true},{"id":"pergunta-235","sourceId":235,"title":"Como conferir a incidência e o vencimento de eventual taxa sobre resíduos de saúde?","originalTitle":"Quando ocorre o fato gerador e vence a TRSS?","sourcePage":73,"answer":"A existência, a ocorrência do fato gerador e o vencimento precisam de confirmação na regra de Aracaju. As datas e categorias de São Paulo em 2013 não devem ser utilizadas.","review":true},{"id":"pergunta-236","sourceId":236,"title":"Como verificar o lançamento de eventual taxa sobre resíduos de saúde?","originalTitle":"Como é lançada a TRSS?","sourcePage":73,"answer":"A forma de lançamento só pode ser definida após identificar eventual tributo municipal e o órgão responsável. Não confunda cobrança de empresa de coleta ou contrato de tratamento com lançamento tributário.","review":true},{"id":"pergunta-237","sourceId":237,"title":"Como solicitar segunda via de eventual cobrança municipal sobre resíduos de saúde?","originalTitle":"Como emitir a 2ª via da guia de pagamento da TRSS?","sourcePage":74,"answer":"Se houver cobrança municipal aplicável, solicite a segunda via da receita e do estabelecimento corretos ao órgão responsável. A guia paulista de TRSS não é documento de arrecadação de Aracaju.","review":true}]},{"number":21,"id":"capitulo-21","short":"Contribuição de melhoria","title":"Contribuição de melhoria","description":"Obra pública, valorização imobiliária, lançamento, pagamento e revisão da contribuição.","subtitle":"Obras públicas e valorização do imóvel","icon":"map","originalTitle":"CONTRIBUIÇÃO DE MELHORIA","sourcePage":74,"note":"A apresentação do tema não indica uma cobrança existente para seu imóvel. Contribuição de melhoria exige os requisitos legais e um lançamento específico.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-239","sourceId":239,"title":"O que é a Contribuição de Melhoria?","originalTitle":"O que é a Contribuição de Melhoria?","sourcePage":74,"answer":"A contribuição de melhoria é um tributo relacionado à valorização imobiliária decorrente de obra pública, nos termos legais. Não é o mesmo que IPTU nem uma cobrança automática por qualquer intervenção urbana.","review":false},{"id":"pergunta-240","sourceId":240,"title":"Qual o fato gerador da Contribuição de Melhoria?","originalTitle":"Qual o fato gerador da Contribuição de Melhoria?","sourcePage":74,"answer":"O fato gerador envolve a valorização do imóvel decorrente da obra, conforme os requisitos legais. A realização de obra pública, isoladamente, não substitui a demonstração e o procedimento necessários à cobrança.","review":true},{"id":"pergunta-241","sourceId":241,"title":"Quem é o sujeito passivo da Contribuição de Melhoria?","originalTitle":"Quem é o sujeito passivo da Contribuição de Melhoria?","sourcePage":74,"answer":"O sujeito passivo deve ser identificado conforme a legislação e o vínculo com o imóvel beneficiado. Confira a identificação do imóvel e do responsável no lançamento específico.","review":true},{"id":"pergunta-242","sourceId":242,"title":"Como é calculada a Contribuição de Melhoria?","originalTitle":"Como é calculada a Contribuição de Melhoria?","sourcePage":75,"answer":"O cálculo exige os critérios legais de valorização, limites e distribuição do custo da obra. Solicite a memória de cálculo e a documentação do lançamento, em vez de adotar um percentual genérico.","review":true},{"id":"pergunta-243","sourceId":243,"title":"Como é lançada e notificada a Contribuição de Melhoria?","originalTitle":"Como é lançada e notificada a Contribuição de Melhoria?","sourcePage":75,"answer":"O lançamento e a ciência devem observar o procedimento e as informações exigidos pela legislação. Confira a obra, o imóvel, o valor, o fundamento e as condições para contestação.","review":true},{"id":"pergunta-244","sourceId":244,"title":"Como é feita a arrecadação da Contribuição de Melhoria?","originalTitle":"Como é feita a arrecadação da Contribuição de Melhoria?","sourcePage":75,"answer":"A arrecadação depende de lançamento válido e da guia oficial correspondente. Confirme se há cobrança efetiva em Aracaju para a obra e o imóvel, pois a presença do tema no guia não significa lançamento existente.","review":true},{"id":"pergunta-245","sourceId":245,"title":"Como deve ser feito o pagamento da Contribuição de Melhoria?","originalTitle":"Como deve ser feito o pagamento da Contribuição de Melhoria?","sourcePage":75,"answer":"Utilize a guia e as condições indicadas no lançamento específico, verificando eventual parcelamento legal. Guarde o comprovante e acompanhe a baixa do valor.","review":true},{"id":"pergunta-246","sourceId":246,"title":"Qual o valor da Contribuição de Melhoria se esta não for paga até a data do vencimento?","originalTitle":"Qual o valor da Contribuição de Melhoria se esta não for paga até a data do vencimento?","sourcePage":75,"answer":"Após o vencimento, os encargos dependem da legislação aplicável ao crédito. Solicite guia atualizada da contribuição, sem usar multa ou juros do roteiro paulista.","review":true},{"id":"pergunta-247","sourceId":247,"title":"Como emitir a 2ª via da guia de pagamento da Contribuição de Melhoria?","originalTitle":"Como emitir a 2ª via da guia de pagamento da Contribuição de Melhoria?","sourcePage":76,"answer":"Informe o número do lançamento, a obra, o imóvel e o período para solicitar nova guia. Se não localizar o serviço eletrônico, consulte o órgão municipal indicado na notificação.","review":true},{"id":"pergunta-248","sourceId":248,"title":"Como reclamar de incorreção dos dados do lançamento da Contribuição de Melhoria?","originalTitle":"Como reclamar de incorreção dos dados do lançamento da Contribuição de Melhoria?","sourcePage":76,"answer":"Apresente contestação fundamentada com a identificação do lançamento e a prova da divergência de imóvel, valorização ou cálculo. Confirme o prazo e os efeitos do recurso no procedimento local.","review":true},{"id":"pergunta-249","sourceId":249,"title":"Quem está isento da Contribuição de Melhoria?","originalTitle":"Quem está isento da Contribuição de Melhoria?","sourcePage":76,"answer":"Uma isenção depende de previsão legal específica. Não presuma dispensa por renda, condição pessoal ou finalidade do imóvel sem identificar a hipótese e os requisitos municipais.","review":true},{"id":"pergunta-250","sourceId":250,"title":"Como solicitar a isenção da Contribuição de Melhoria?","originalTitle":"Como solicitar a isenção da Contribuição de Melhoria?","sourcePage":76,"answer":"Solicite o reconhecimento do benefício com o fundamento legal e a documentação exigida. O pedido deve identificar a contribuição, a obra e o imóvel abrangido.","review":true},{"id":"pergunta-251","sourceId":251,"title":"Onde solicitar informações sobre o andamento do processo de pedido de isenção?","originalTitle":"Onde solicitar informações sobre o andamento do processo de pedido de isenção?","sourcePage":77,"answer":"Acompanhe o protocolo no canal informado pelo órgão responsável. Confira exigências e comunicações, pois a simples abertura do pedido não significa concessão do benefício.","review":true},{"id":"pergunta-252","sourceId":252,"title":"Em quais casos não incide a Contribuição de Melhoria?","originalTitle":"Em quais casos não incide a Contribuição de Melhoria?","sourcePage":77,"answer":"Pode não haver incidência quando não ocorrer a hipótese legal de valorização ou não estiverem presentes os pressupostos exigidos. O caso deve ser analisado a partir da obra, do imóvel e do procedimento, distinguindo não incidência de isenção.","review":true}]},{"number":22,"id":"capitulo-22","short":"Iluminação pública","title":"Iluminação pública e COCIP","description":"Contribuição para custeio, enquadramento, tabela de valores e conferência da cobrança.","subtitle":"Contribuição para o Custeio do Serviço de Iluminação Pública","icon":"bulb","originalTitle":"CONTRIBUIÇÃO PARA CUSTEIO DA ILUMINAÇÃO PÚBLICA - COSIP","sourcePage":77,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Lei municipal nº 4.453/2013 — COCIP","url":"https://fazenda.aracaju.se.gov.br/app-estatico/pdf/lo_4453_2013.pdf"}],"topics":[{"id":"pergunta-254","sourceId":254,"title":"O que é a COCIP de Aracaju?","originalTitle":"O que é a COSIP?","sourcePage":77,"answer":"Em Aracaju, a denominação publicada é COCIP: Contribuição para o Custeio do Serviço de Iluminação Pública. Sua base local inclui a Lei nº 4.453/2013 e alterações; COSIP é a sigla utilizada no guia paulista.","review":false},{"id":"pergunta-255","sourceId":255,"title":"Quem deve pagar a COCIP?","originalTitle":"Quem deve pagar a COSIP?","sourcePage":77,"answer":"Os contribuintes e os critérios de enquadramento são definidos na lei municipal. Verifique a classificação e a unidade consumidora ou imóvel envolvidos, especialmente em casos de alteração cadastral e benefícios.","review":true},{"id":"pergunta-256","sourceId":256,"title":"Como é cobrada a COCIP?","originalTitle":"Como é cobrada a COSIP?","sourcePage":77,"answer":"A forma de cobrança e os valores devem ser conferidos na lei e na tabela municipal de COCIP, juntamente com o documento em que a contribuição aparece. Eventual divergência pode exigir consulta à distribuidora e à SEMFAZ, conforme a origem.","review":true},{"id":"pergunta-257","sourceId":257,"title":"Como é reajustada a COCIP?","originalTitle":"Como é reajustada a COSIP?","sourcePage":77,"answer":"Os critérios de atualização dependem da legislação local e da tabela vigente. Não utilize a regra paulista nem confunda reajuste de tarifa de energia com alteração automática de contribuição municipal.","review":true},{"id":"pergunta-258","sourceId":258,"title":"Quem está isento da COCIP?","originalTitle":"Quem está isento da COSIP?","sourcePage":78,"answer":"A isenção ou outra dispensa exige enquadramento na norma de Aracaju. Confira a hipótese, a documentação e o órgão que analisa o pedido antes de retirar ou deixar de pagar a contribuição.","review":true}]},{"number":23,"id":"capitulo-23","short":"Cadastro mobiliário","title":"Cadastro mobiliário e inscrição municipal","description":"Abertura, alteração, baixa, reativação e documentos cadastrais de atividades econômicas.","subtitle":"Cadastro e licenciamento da atividade","icon":"clipboard","originalTitle":"CADASTRO DE CONTRIBUINTES MOBILIÁRIOS – CCM","sourcePage":78,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-260","sourceId":260,"title":"O que é o cadastro mobiliário e a inscrição municipal?","originalTitle":"O que é CCM?","sourcePage":78,"answer":"O cadastro mobiliário registra contribuintes e atividades econômicas para fins municipais. O guia paulista usa a sigla CCM; em Aracaju, consulte sua inscrição e os serviços municipais de cadastro e licenciamento.","review":false},{"id":"pergunta-261","sourceId":261,"title":"Quem deve se inscrever no cadastro mobiliário?","originalTitle":"Quem deve se inscrever no CCM?","sourcePage":78,"answer":"A obrigação de inscrição depende da atividade, da pessoa e das regras municipais. Empresas e profissionais devem verificar cadastro, endereço, atividade e regime antes de iniciar ou alterar a atuação.","review":true},{"id":"pergunta-262","sourceId":262,"title":"Quando o sujeito passivo deve se inscrever no cadastro mobiliário?","originalTitle":"Quando o sujeito passivo deve se inscrever no CCM?","sourcePage":79,"answer":"Confirme o momento e o prazo exigidos no procedimento de registro e licenciamento. Para atividades empresariais, a integração com o SLIM e a Redesim pode fazer parte da abertura e das alterações.","review":true},{"id":"pergunta-263","sourceId":263,"title":"Como fazer a inscrição, alteração e cancelamento do cadastro mobiliário?","originalTitle":"Como fazer a inscrição, alteração e cancelamento do CCM?","sourcePage":79,"answer":"Use o procedimento municipal correspondente à abertura, alteração ou baixa da atividade. Confira se a integração com o registro empresarial alcança todos os dados fiscais e acompanhe a conclusão da inscrição.","review":true},{"id":"pergunta-264","sourceId":264,"title":"Como fazer a inscrição on-line?","originalTitle":"Como fazer a inscrição on-line?","sourcePage":79,"answer":"O portal municipal direciona o licenciamento integrado ao SLIM. Escolha o procedimento relacionado à atividade e confira a identificação e os documentos pedidos; autônomos e situações especiais podem seguir orientação própria.","review":true},{"id":"pergunta-265","sourceId":265,"title":"Como e quando fazer o cancelamento da inscrição no cadastro mobiliário?","originalTitle":"Como e quando fazer o cancelamento da inscrição no CCM?","sourcePage":79,"answer":"A baixa deve ser solicitada pelo procedimento aplicável quando houver encerramento ou outra hipótese admitida. Confira a data reconhecida e regularize obrigações anteriores; fechar o estabelecimento fisicamente não cancela automaticamente a inscrição.","review":true},{"id":"pergunta-266","sourceId":266,"title":"Como e quando efetuar alteração de dados cadastrais no cadastro mobiliário?","originalTitle":"Como e quando efetuar alteração de dados cadastrais no CCM?","sourcePage":80,"answer":"Mudanças de endereço, atividade, representação ou outros dados relevantes devem ser comunicadas no prazo local. Verifique o resultado no cartão ou documento cadastral e confirme eventuais efeitos sobre licenças.","review":true},{"id":"pergunta-267","sourceId":267,"title":"Como a SEMFAZ pode atualizar seus cadastros?","originalTitle":"Como a Secretaria Municipal de Finanças e Desenvolvimento Econômico pode atualizar seus cadastros?","sourcePage":80,"answer":"A administração pode atualizar informações pelos procedimentos legais e por dados obtidos em análise, fiscalização ou integração cadastral. Confira a alteração e exerça o direito de correção se identificar divergência.","review":false},{"id":"pergunta-268","sourceId":268,"title":"Como promover a reativação de inscrição no cadastro mobiliário?","originalTitle":"Como promover a reativação de inscrição no CCM?","sourcePage":81,"answer":"A reativação depende da situação da inscrição e do procedimento autorizado pelo município. Solicite orientação antes de operar novamente e verifique licenças, declarações e débitos necessários à regularização.","review":true},{"id":"pergunta-269","sourceId":269,"title":"Quais os casos de reativação do cadastro mobiliário em que os tributos relativos ao período desativado não precisam ser pagos?","originalTitle":"Quais os casos de reativação do CCM em que os tributos relativos ao período desativado não precisam ser pagos?","sourcePage":81,"answer":"A dispensa de tributos de período desativado exige fundamento legal e reconhecimento da situação. Não presuma que ausência de atividade ou cadastro inativo perdoa débitos; apresente os documentos e peça análise.","review":true},{"id":"pergunta-270","sourceId":270,"title":"O que é o documento de dados cadastrais do contribuinte?","originalTitle":"O que é a Ficha de Dados Cadastrais (FDC)?","sourcePage":81,"answer":"É um documento que apresenta informações do cadastro do contribuinte. Em Aracaju, consulte o cartão de inscrição ou documento municipal equivalente; ele informa o cadastro e não substitui certidão de regularidade fiscal.","review":false}]},{"number":24,"id":"capitulo-24","short":"Prestadores de fora","title":"Prestadores de outros municípios","description":"Tratamento de serviços contratados de prestadores externos e cuidados com exigências cadastrais.","subtitle":"Prestação de serviços entre municípios","icon":"globe","originalTitle":"CADASTRO DE PRESTADORES DE OUTROS MUNICÍPIOS - CPOM","sourcePage":82,"note":"O STF, no Tema 1.020, afastou o modelo de cadastro obrigatório de prestador externo associado à retenção de ISS apenas por falta de inscrição. As demais hipóteses legais de retenção precisam ser analisadas separadamente; não foi confirmado CPOM equivalente em Aracaju.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"STF — Tema 1.020, prestadores externos","url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5563078&numeroProcesso=1167509&numeroTema=1020"}],"topics":[{"id":"pergunta-272","sourceId":272,"title":"O que significa CPOM e como tratar esse tema em Aracaju?","originalTitle":"O que é o CPOM?","sourcePage":82,"answer":"CPOM é a sigla do cadastro de prestadores de outros municípios tratado no guia paulista. Sua utilização como obrigação de Aracaju não foi confirmada; a contratação deve seguir as regras atuais de incidência e retenção do ISS.","review":true},{"id":"pergunta-273","sourceId":273,"title":"Existe obrigação local de cadastro para prestadores de outros municípios?","originalTitle":"Quem está obrigado a inscrever-se no CPOM?","sourcePage":82,"answer":"Não foi confirmada obrigação local de cadastro com essa denominação. Verifique o enquadramento do serviço com a SEMFAZ antes de exigir inscrição de prestador estabelecido em outro município.","review":true},{"id":"pergunta-274","sourceId":274,"title":"Como verificar as etapas de eventual cadastro de prestador externo?","originalTitle":"Quais são as etapas previstas para o cadastro no CPOM?","sourcePage":82,"answer":"O roteiro de etapas do PDF pertence ao procedimento paulista. Para Aracaju, não há sequência local confirmada nesta versão; solicite orientação oficial se o serviço municipal exigir cadastro ou declaração próprios.","review":true},{"id":"pergunta-275","sourceId":275,"title":"Como verificar o canal de eventual inscrição de prestador externo?","originalTitle":"Como é feita a inscrição no CPOM?","sourcePage":83,"answer":"Não utilize o formulário de CPOM de São Paulo para Aracaju. Antes de encaminhar uma inscrição, confirme a existência de procedimento local e sua finalidade.","review":true},{"id":"pergunta-276","sourceId":276,"title":"Como proceder após preencher um formulário de cadastro aplicável?","originalTitle":"Qual o procedimento após o preenchimento do formulário eletrônico?","sourcePage":83,"answer":"A entrega e a validação de um eventual formulário devem seguir o canal local oficialmente indicado. O preenchimento de documento de outro município não produz inscrição em Aracaju.","review":true},{"id":"pergunta-277","sourceId":277,"title":"Quais documentos podem ser exigidos em eventual cadastro de prestador externo?","originalTitle":"Quais são os documentos que devem ser encaminhados para a Secretaria Municipal de Finanças e Desenvolvimento Econômico para inscrição no CPOM?","sourcePage":83,"answer":"A lista paulista não foi adotada como exigência de Aracaju. Somente envie documentos quando houver solicitação e procedimento municipal identificados, observando sua finalidade.","review":true},{"id":"pergunta-278","sourceId":278,"title":"Há exigência ou dispensa de fotografias do estabelecimento?","originalTitle":"Quando são dispensadas as fotografias das instalações internas do estabelecimento?","sourcePage":83,"answer":"As dispensas de fotografia mencionadas no PDF pertencem ao procedimento de São Paulo. Não foi confirmada exigência local equivalente nem sua dispensa.","review":true},{"id":"pergunta-279","sourceId":279,"title":"Como conferir o prazo de análise de eventual cadastro de prestador externo?","originalTitle":"Qual o prazo para a Prefeitura inscrever o prestador de serviços?","sourcePage":84,"answer":"Não há prazo local confirmado para inscrição em CPOM nesta versão. Eventual cadastro municipal deve seguir os prazos do procedimento oficial correspondente.","review":true},{"id":"pergunta-280","sourceId":280,"title":"Como consultar uma inscrição e esclarecer dúvidas sobre prestador externo?","originalTitle":"Como o prestador pode verificar a situação de sua inscrição e esclarecer dúvidas?","sourcePage":84,"answer":"Para inscrição ou obrigação de prestador externo efetivamente exigida, consulte a SEMFAZ com CNPJ, serviço e protocolo. A consulta paulista não comprova situação cadastral de Aracaju.","review":true},{"id":"pergunta-281","sourceId":281,"title":"Como contestar o indeferimento de um pedido cadastral municipal?","originalTitle":"O que fazer se o pedido de inscrição não for deferido?","sourcePage":84,"answer":"Uma decisão municipal deve ser contestada pelo canal e no prazo que constam do ato recebido. Não utilize o recurso paulista nem abra novo protocolo sem orientação do procedimento local.","review":true},{"id":"pergunta-282","sourceId":282,"title":"Como identificar o prestador em eventual cadastro municipal?","originalTitle":"Como o prestador será identificado no CPOM?","sourcePage":84,"answer":"A identificação deve seguir o cadastro ou documento municipal efetivamente utilizado. O número de CPOM paulista não substitui o CNPJ nem eventual identificação local.","review":true},{"id":"pergunta-283","sourceId":283,"title":"Como conferir os dados cadastrais de um prestador de serviços?","originalTitle":"Como o tomador de serviços pode verificar se o prestador de serviços está cadastrado?","sourcePage":84,"answer":"Confira os documentos e a situação fiscal do prestador nos canais competentes à finalidade da contratação. Não utilize o cadastro paulista como requisito automático de Aracaju.","review":true},{"id":"pergunta-284","sourceId":284,"title":"A ausência de cadastro do prestador externo autoriza retenção automática do ISS?","originalTitle":"O que deve fazer o tomador do serviço (Pessoa Jurídica) se o prestador que estiver obrigado a inscrever-se no CPOM não o fizer?","sourcePage":85,"answer":"A falta de cadastro externo, isoladamente, não deve ser usada como fundamento automático para retenção. Confira as hipóteses legais de responsabilidade e o município ao qual o ISS é devido.","review":true},{"id":"pergunta-285","sourceId":285,"title":"Como verificar as consequências da falta de atualização cadastral?","originalTitle":"O que fará a Secretaria Municipal de Finanças e Desenvolvimento Econômico se o prestador não atualizar seus dados?","sourcePage":85,"answer":"Qualquer exigência de atualização deve ter fundamento e canal municipal identificados. As consequências previstas no procedimento paulista não foram atribuídas automaticamente ao prestador em Aracaju.","review":true}]},{"number":25,"id":"capitulo-25","short":"Pendências e cadastros","title":"Pendências e cadastros informativos","description":"Identificação, consulta, regularização e atualização de pendências fiscais.","subtitle":"Débitos, registros e regularização","icon":"alert","originalTitle":"CADIN MUNICIPAL","sourcePage":85,"note":"O CADIN citado no roteiro é de São Paulo. Não foi confirmado cadastro de Aracaju com o mesmo nome, prazos e efeitos; consulte a origem de cada pendência local.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-287","sourceId":287,"title":"O que é um cadastro informativo de pendências e como verificar sua existência local?","originalTitle":"O que é o Cadastro Informativo Municipal - CADIN MUNICIPAL?","sourcePage":85,"answer":"O CADIN municipal do PDF é um cadastro informativo de pendências de São Paulo. Não foi confirmada uma estrutura local equivalente com o mesmo nome; em Aracaju, identifique a situação fiscal e a eventual inscrição em dívida ativa pelos canais próprios.","review":true},{"id":"pergunta-288","sourceId":288,"title":"Quem é responsável por incluir ou excluir uma pendência de um cadastro?","originalTitle":"Quem faz as inclusões e as exclusões dos devedores no CADIN MUNICIPAL?","sourcePage":86,"answer":"Inclusão e exclusão em cadastro restritivo dependem do órgão e da norma que o instituem. Para Aracaju, solicite identificação da origem da pendência e da autoridade responsável pela cobrança ou pelo registro.","review":true},{"id":"pergunta-289","sourceId":289,"title":"Como verificar os procedimentos e prazos de inclusão de pendências?","originalTitle":"Quais são os procedimentos efetuados pela Administração e prazo para a inclusão de pendências no CADIN MUNICIPAL","sourcePage":86,"answer":"Comunicação, prazo e efeitos de inclusão precisam estar definidos no procedimento aplicável. As regras do CADIN de São Paulo não devem ser utilizadas para afirmar inclusão ou restrição em Aracaju.","review":true},{"id":"pergunta-290","sourceId":290,"title":"Como fazer para regularizar a pendência?","originalTitle":"Como fazer para regularizar a pendência?","sourcePage":86,"answer":"Identifique o débito e verifique se cabe pagamento, parcelamento, correção ou contestação. Guarde o protocolo e os comprovantes e acompanhe a baixa no órgão que apontou a pendência.","review":false},{"id":"pergunta-291","sourceId":291,"title":"Quais informações podem constar de um cadastro de pendências?","originalTitle":"Quais as informações que constam no CADIN MUNICIPAL?","sourcePage":86,"answer":"As informações exibidas dependem do cadastro e de sua base legal. Na consulta local, confira identificação do devedor, origem, exercício e situação do crédito, observadas as condições de acesso.","review":true},{"id":"pergunta-292","sourceId":292,"title":"Como acompanhar a baixa após regularizar a situação?","originalTitle":"Depois de regularizada a situação, em quanto tempo o nome do devedor será excluído do CADIN MUNICIPAL?","sourcePage":87,"answer":"O prazo de atualização depende do órgão e do processamento da regularização. Confirme a baixa no canal correspondente e solicite análise se a restrição persistir, sem aplicar o prazo do CADIN paulista.","review":true},{"id":"pergunta-293","sourceId":293,"title":"Quando é exigida consulta prévia a um cadastro de pendências?","originalTitle":"Quem é obrigado a fazer consulta prévia ao CADIN MUNICIPAL?","sourcePage":87,"answer":"A obrigação de consulta prévia exige previsão específica para o órgão e a finalidade. Não foi confirmada, nesta versão, regra de Aracaju equivalente à consulta de CADIN descrita no PDF.","review":true},{"id":"pergunta-294","sourceId":294,"title":"Quais débitos podem ser registrados em cadastro informativo?","originalTitle":"Quais os débitos municipais que podem ser incluídos no CADIN MUNICIPAL?","sourcePage":87,"answer":"A natureza dos débitos registráveis depende da lei do cadastro. Diferencie tributos, outras receitas, dívida ativa e cobrança judicial; não atribua a todos eles as mesmas consequências.","review":true},{"id":"pergunta-295","sourceId":295,"title":"Como consultar a situação de uma pendência municipal?","originalTitle":"Como fazer para acessar e consultar sua situação no CADIN MUNICIPAL?","sourcePage":87,"answer":"Consulte os serviços municipais de débitos e certidões e o órgão responsável pela cobrança. Caso receba referência a cadastro restritivo específico, peça o nome, a base legal e o canal oficial de consulta.","review":true},{"id":"pergunta-296","sourceId":296,"title":"Em que situações um registro de pendência pode ficar suspenso?","originalTitle":"Em que casos o registro no CADIN ficará suspenso?","sourcePage":88,"answer":"A suspensão de registro ou cobrança depende da hipótese e do reconhecimento previstos em lei. Pedido de revisão ou parcelamento não deve ser considerado suficiente sem conferir seus efeitos no caso concreto.","review":true}]},{"number":26,"id":"capitulo-26","short":"Acesso e senha","title":"Acesso aos serviços e senha","description":"Cadastro, autenticação, permissões e recuperação de acesso nos serviços eletrônicos.","subtitle":"Credenciais e acesso aos sistemas","icon":"lock","originalTitle":"SENHA WEB","sourcePage":88,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-298","sourceId":298,"title":"O que é a senha web?","originalTitle":"O que é a senha web?","sourcePage":88,"answer":"É a credencial usada para acessar um sistema eletrônico, quando ele admite usuário e senha. Em Aracaju, siga o cadastro e as formas de acesso apresentadas no serviço efetivamente utilizado.","review":false},{"id":"pergunta-299","sourceId":299,"title":"O que permite a senha web?","originalTitle":"O que permite a senha web?","sourcePage":88,"answer":"O acesso permite utilizar os serviços habilitados para o perfil do usuário. Cadastros de pessoa física, empresa e representante podem ter permissões diferentes e exigir comprovação de vínculo.","review":false},{"id":"pergunta-300","sourceId":300,"title":"Quando a senha web é obrigatória?","originalTitle":"Quando a senha web é obrigatória?","sourcePage":88,"answer":"A exigência depende do sistema e do serviço; pode haver outras formas de autenticação, como certificado ou acesso integrado. Confira a opção exibida no canal oficial e mantenha sua conta atualizada.","review":true},{"id":"pergunta-301","sourceId":301,"title":"Como cadastrar a senha web?","originalTitle":"Como cadastrar a senha web?","sourcePage":88,"answer":"Utilize a opção de primeiro acesso ou cadastro no sistema municipal correspondente. Informe seus dados e complete a validação exigida; representantes devem conferir o procedimento de vinculação ao contribuinte.","review":true},{"id":"pergunta-302","sourceId":302,"title":"Quando é desbloqueada a senha?","originalTitle":"Quando é desbloqueada a senha?","sourcePage":89,"answer":"A liberação depende da validação do cadastro ou do atendimento à exigência apresentada. Use a recuperação de acesso ou o atendimento oficial se houver bloqueio, sem presumir o prazo de desbloqueio paulista.","review":true}]},{"number":27,"id":"capitulo-27","short":"Parcelamento de débitos","title":"Parcelamento de débitos municipais","description":"Elegibilidade, proposta, adesão, pagamento e consequências do descumprimento do acordo.","subtitle":"Regularização de créditos municipais","icon":"calendar","originalTitle":"PARCELAMENTO ADMINISTRATIVO DE DÉBITOS TRIBUTÁRIOS - PAT","sourcePage":89,"note":"PAT é a denominação do programa paulista. A modalidade, a elegibilidade, os benefícios e a disponibilidade de adesão ao parcelamento de Aracaju precisam ser conferidos no momento do pedido.","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"},{"label":"Benefícios fiscais — Transparência Aracaju","url":"https://transparencia.aracaju.se.gov.br/prefeitura/prestacao-de-contas/"}],"topics":[{"id":"pergunta-304","sourceId":304,"title":"O que é o parcelamento de débitos municipais?","originalTitle":"O que é o PAT?","sourcePage":89,"answer":"Parcelamento é uma forma de regularizar créditos municipais nas condições admitidas pela legislação. PAT é a denominação do programa do guia paulista; para Aracaju, confira o parcelamento ou programa efetivamente vigente.","review":false},{"id":"pergunta-305","sourceId":305,"title":"Quem seleciona os débitos do parcelamento?","originalTitle":"Quem seleciona os débitos a serem incluídos no PAT?","sourcePage":89,"answer":"O interessado deve conferir e selecionar os débitos elegíveis, com validação pelo sistema ou órgão responsável. Leia a proposta antes de confirmar, inclusive os períodos, encargos e créditos que ficarão fora do acordo.","review":false},{"id":"pergunta-306","sourceId":306,"title":"Quais débitos podem ser incluídos no parcelamento?","originalTitle":"Quais débitos podem ser incluídos no PAT?","sourcePage":89,"answer":"A elegibilidade depende do tributo, da situação do crédito e das regras do parcelamento. Débitos em dívida ativa, judicializados ou de ITBI podem ter tratamentos próprios e exigir outro procedimento.","review":true},{"id":"pergunta-307","sourceId":307,"title":"Como solicitar parcelamento de débitos municipais?","originalTitle":"Como aderir ao PAT?","sourcePage":89,"answer":"Consulte a modalidade de parcelamento municipal aplicável e solicite a simulação ou proposta pelo canal oficial. Verifique identificação, valores, condições e efeitos da adesão antes de formalizar.","review":false},{"id":"pergunta-308","sourceId":308,"title":"Quais etapas seguir para aderir ao parcelamento?","originalTitle":"Qual roteiro deve ser seguido para aderir ao PAT?","sourcePage":89,"answer":"Identifique os débitos, confira sua elegibilidade, examine a proposta e cumpra a formalização e o primeiro pagamento quando exigidos. Depois, acompanhe as guias e mantenha o pagamento das parcelas no prazo.","review":false},{"id":"pergunta-309","sourceId":309,"title":"Quais são os efeitos da adesão sobre defesas e recursos?","originalTitle":"O que implica a formalização do PAT em relação a defesas e recursos administrativos?","sourcePage":90,"answer":"A adesão pode envolver reconhecimento do débito e condições relacionadas a defesas ou recursos. Leia o termo e confirme os efeitos jurídicos antes de aceitar, principalmente quando houver processo em discussão.","review":true},{"id":"pergunta-310","sourceId":310,"title":"Como conferir o prazo para adesão ao parcelamento?","originalTitle":"Qual o prazo para adesão ao PAT?","sourcePage":90,"answer":"Parcelamento ordinário e programas especiais podem ter prazos de adesão diferentes. Consulte o ato e o serviço vigentes; a menção ao PODE ou a programa anterior não significa que a janela de adesão permaneça aberta.","review":true},{"id":"pergunta-311","sourceId":311,"title":"Como verificar quantas parcelas são permitidas?","originalTitle":"Quantas parcelas são permitidas no PAT?","sourcePage":90,"answer":"O número de parcelas, o valor mínimo e eventual entrada dependem da modalidade e do crédito. Solicite a proposta válida para o seu débito, sem utilizar os limites do PAT paulista.","review":true},{"id":"pergunta-312","sourceId":312,"title":"Quais benefícios podem existir no parcelamento?","originalTitle":"Quais os benefícios para quem adere ao PAT?","sourcePage":90,"answer":"O parcelamento pode facilitar a regularização e produzir os efeitos legais enquanto cumprido. Desconto de multa, juros ou principal só existe quando autorizado para a modalidade, e não é um benefício automático de qualquer acordo.","review":true},{"id":"pergunta-313","sourceId":313,"title":"Como conferir o vencimento das parcelas?","originalTitle":"Quando vencem as parcelas do PAT?","sourcePage":91,"answer":"Confira as datas no termo e em cada guia. Organize o acompanhamento mensal ou conforme a periodicidade do acordo; problemas no recebimento da guia devem ser resolvidos antes do vencimento.","review":true},{"id":"pergunta-314","sourceId":314,"title":"Quais situações podem causar a rescisão do parcelamento?","originalTitle":"Quais as situações que implicam em rompimento e exclusão do sujeito passivo do PAT?","sourcePage":91,"answer":"Atraso, falta de pagamento ou descumprimento de condições podem causar rescisão, conforme o termo. Confirme o número de parcelas e os demais eventos previstos na sua modalidade de acordo.","review":true},{"id":"pergunta-315","sourceId":315,"title":"O que acontece se o parcelamento for rescindido?","originalTitle":"O que acontece se o PAT for rompido?","sourcePage":91,"answer":"A rescisão pode tornar o saldo exigível e levar à retomada da cobrança e à perda de benefícios previstos. Solicite o demonstrativo atualizado e orientação sobre regularização ou nova modalidade admitida.","review":true},{"id":"pergunta-316","sourceId":316,"title":"Como verificar limites de parcelamento e reparcelamento?","originalTitle":"Quantos parcelamentos são permitidos?","sourcePage":91,"answer":"A quantidade de acordos, a possibilidade de reparcelamento e eventuais restrições dependem da norma. Não há um limite único que possa ser importado do programa paulista.","review":true},{"id":"pergunta-317","sourceId":317,"title":"É possível antecipar parcelas do acordo?","originalTitle":"É permitido antecipar parcelas do PAT?","sourcePage":91,"answer":"A antecipação depende das condições do acordo e da emissão da guia adequada. Peça o cálculo do saldo ou das parcelas que pretende quitar; não pague valores avulsos sem vinculação ao parcelamento.","review":true}]},{"number":28,"id":"capitulo-28","short":"Certidões e processos","title":"Certidões e acompanhamento de processos","description":"Tipos de certidão, emissão, autenticidade, validade e acompanhamento de requerimentos.","subtitle":"Comprovação da situação fiscal","icon":"filecheck","originalTitle":"CERTIDÕES","sourcePage":92,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-319","sourceId":319,"title":"Quem pode solicitar certidão?","originalTitle":"Quem pode solicitar certidão?","sourcePage":92,"answer":"O pedido deve observar a finalidade, o tipo de certidão e as regras de identificação e representação. Certidões com dados protegidos podem exigir acesso do contribuinte ou representante habilitado.","review":false},{"id":"pergunta-320","sourceId":320,"title":"Como solicitar as Certidões Imobiliárias?","originalTitle":"Como solicitar as Certidões Imobiliárias?","sourcePage":92,"answer":"Acesse o serviço municipal de certidões e identifique o imóvel pela inscrição ou dado solicitado. Escolha o documento adequado à finalidade; se a emissão não for possível, consulte o motivo e o canal de análise.","review":false},{"id":"pergunta-321","sourceId":321,"title":"Quais os tipos de certidões existentes?","originalTitle":"Quais os tipos de certidões existentes?","sourcePage":92,"answer":"Entre as situações fiscais estão certidão negativa, positiva e positiva com efeitos de negativa, conforme os requisitos legais. Documentos cadastrais e certidões específicas de imóvel ou atividade têm finalidades próprias.","review":false},{"id":"pergunta-322","sourceId":322,"title":"Quais as certidões imobiliárias emitidas?","originalTitle":"Quais as certidões imobiliárias emitidas?","sourcePage":92,"answer":"Os tipos disponíveis devem ser confirmados no catálogo municipal. Certidão de situação fiscal do imóvel e documento de dados cadastrais não são equivalentes; informe a finalidade para pedir o documento correto.","review":true},{"id":"pergunta-323","sourceId":323,"title":"Quais as certidões mobiliárias emitidas?","originalTitle":"Quais as certidões mobiliárias emitidas?","sourcePage":93,"answer":"Consulte os documentos fiscais e cadastrais disponíveis para a inscrição ou o contribuinte. Uma certidão de débitos de atividade pode não abranger a situação imobiliária e vice-versa.","review":true},{"id":"pergunta-324","sourceId":324,"title":"O que é a declaração cadastral?","originalTitle":"O que é a declaração cadastral?","sourcePage":93,"answer":"É um documento que apresenta dados registrados no cadastro. Ele não comprova, por si só, quitação de tributos, propriedade registrada ou regularidade de todas as licenças.","review":false},{"id":"pergunta-325","sourceId":325,"title":"Para que serve a Certidão Negativa de Tributos Mobiliários?","originalTitle":"Para que serve a Certidão Negativa de Tributos Mobiliários?","sourcePage":93,"answer":"A certidão negativa comprova a situação fiscal no alcance e na data definidos pelo documento. Confira quais receitas e períodos abrange; ela não deve ser interpretada como declaração irrestrita sobre qualquer obrigação.","review":false},{"id":"pergunta-326","sourceId":326,"title":"Como emitir a Certidão Negativa de Tributos Mobiliários e confirmar sua autenticidade?","originalTitle":"Como emitir a Certidão Negativa de Tributos Mobiliários e confirmar sua autenticidade?","sourcePage":93,"answer":"Solicite o documento no serviço oficial e depois valide o código ou os dados de autenticidade no canal indicado. Compare contribuinte, inscrição, tipo, data e validade com a versão apresentada.","review":false},{"id":"pergunta-327","sourceId":327,"title":"Como órgãos da Administração Pública podem solicitar a verificação de certidões?","originalTitle":"Como órgãos da Administração Pública podem solicitar a verificação de certidões?","sourcePage":94,"answer":"Use a validação oficial da certidão, observando os dados e o código fornecidos. Se houver dúvida de alcance ou indisponibilidade, solicite confirmação ao órgão emissor pelo canal institucional.","review":false},{"id":"pergunta-328","sourceId":328,"title":"Como requerer Certidões de Tributos Mobiliários que não puderem ser obtidas pela Internet?","originalTitle":"Como requerer Certidões de Tributos Mobiliários que não puderem ser obtidas pela Internet?","sourcePage":94,"answer":"Identifique a mensagem de impedimento e solicite análise pelo atendimento ou requerimento municipal adequado. Apresente dados do contribuinte e documentos pertinentes; a impossibilidade de emissão automática não indica, sozinha, o motivo da pendência.","review":false},{"id":"pergunta-329","sourceId":329,"title":"Qual o prazo para emissão e qual o prazo de validade das Certidões de Tributos Mobiliários?","originalTitle":"Qual o prazo para emissão e qual o prazo de validade das Certidões de Tributos Mobiliários?","sourcePage":94,"answer":"A validade deve constar da certidão, e o prazo de atendimento deve ser confirmado no serviço e na norma municipal. Não use os prazos paulistanos de 2013 para emissão ou aceitação de documento de Aracaju.","review":true},{"id":"pergunta-330","sourceId":330,"title":"Como consultar os textos da legislação tributária municipal?","originalTitle":"Como consultar os textos da legislação tributária municipal?","sourcePage":95,"answer":"Consulte a legislação municipal e o Diário Oficial e confira as alterações da norma. O SLIM reúne referências de legislação; a Lei nº 1.547/1989 deve ser lida com suas modificações, e não apenas no texto original.","review":false},{"id":"pergunta-331","sourceId":331,"title":"Como acompanhar o processo administrativo que tramita na Prefeitura?","originalTitle":"Como acompanhar o processo administrativo que tramita na Prefeitura?","sourcePage":95,"answer":"Utilize o número de protocolo no acompanhamento oficial e consulte a caixa postal ou as comunicações do processo. Atenda às exigências no prazo indicado e mantenha seus dados de contato atualizados.","review":false}]},{"number":29,"id":"capitulo-29","short":"Certificado digital","title":"Certificado digital","description":"Identificação eletrônica, compatibilidade, representação e cuidados com a credencial.","subtitle":"Autenticação e assinatura eletrônica","icon":"shield","originalTitle":"CERTIFICADO DIGITAL","sourcePage":95,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"ITI — informações sobre ICP-Brasil","url":"https://www.gov.br/iti/pt-br/assuntos/icp-brasil"}],"topics":[{"id":"pergunta-333","sourceId":333,"title":"O que é um Certificado Digital?","originalTitle":"O que é um Certificado Digital?","sourcePage":95,"answer":"Certificado digital é uma credencial eletrônica que vincula uma identidade a mecanismos de assinatura e autenticação. Seu uso depende do tipo de certificado, da validade e da aceitação pelo serviço.","review":false},{"id":"pergunta-334","sourceId":334,"title":"Quem são as Pessoas Jurídicas obrigadas à utilização do Certificado Digital?","originalTitle":"Quem são as Pessoas Jurídicas obrigadas à utilização do Certificado Digital?","sourcePage":95,"answer":"A obrigatoriedade depende do sistema, da atividade e dos atos vigentes. Confira a regra do serviço municipal utilizado; o conjunto de empresas obrigado em São Paulo em 2013 não define a obrigação em Aracaju.","review":true},{"id":"pergunta-335","sourceId":335,"title":"Quem são as Pessoas Jurídicas que não estão obrigadas à utilização do Certificado Digital?","originalTitle":"Quem são as Pessoas Jurídicas que não estão obrigadas à utilização do Certificado Digital?","sourcePage":96,"answer":"Dispensas ou formas alternativas de acesso devem estar previstas no serviço correspondente. Porte, regime tributário ou natureza da empresa não devem ser tratados como dispensa sem confirmação.","review":true},{"id":"pergunta-336","sourceId":336,"title":"Qual certificado deverá ser utilizado na NFS-e?","originalTitle":"Qual certificado deverá ser utilizado na NFS-e?","sourcePage":96,"answer":"Utilize apenas o tipo aceito pelo emissor e vinculado à pessoa ou representação correta. Confira as opções e orientações do sistema municipal ou nacional aplicável ao seu regime.","review":true},{"id":"pergunta-337","sourceId":337,"title":"Onde adquirir o Certificado Digital?","originalTitle":"Onde adquirir o Certificado Digital?","sourcePage":96,"answer":"Certificados ICP-Brasil são emitidos por autoridades certificadoras credenciadas. Consulte a relação oficial, o procedimento de identificação e as características do certificado antes de contratar.","review":false},{"id":"pergunta-338","sourceId":338,"title":"Onde obter informações sobre o Certificado Digital?","originalTitle":"Onde obter informações sobre o Certificado Digital?","sourcePage":96,"answer":"Consulte o Instituto Nacional de Tecnologia da Informação (ITI) para informações de ICP-Brasil. Para compatibilidade e uso em um serviço municipal, consulte também as instruções do próprio sistema.","review":false},{"id":"pergunta-339","sourceId":339,"title":"Como o sistema da NFS-e poderá ser acessado por meio de Certificado Digital de Pessoa Física?","originalTitle":"Como o sistema da NFS-e poderá ser acessado por meio de Certificado Digital de Pessoa Física?","sourcePage":97,"answer":"O acesso por certificado de pessoa física depende de o sistema aceitar essa modalidade e de o usuário ter representação ou vínculo válido. Autenticar a pessoa não concede automaticamente poderes para operar pela empresa.","review":true},{"id":"pergunta-340","sourceId":340,"title":"Caso o sistema da NFS-e seja acessado por Pessoa Física, qual Certificado Digital deverá ser utilizado?","originalTitle":"Caso o sistema da NFS-e seja acessado por Pessoa Física, qual Certificado Digital deverá ser utilizado?","sourcePage":97,"answer":"Confira o tipo de certificado de pessoa física aceito e as condições do acesso. Em ambiente ICP-Brasil, o e-CPF é uma modalidade de identificação pessoal, mas sua aceitação e a autorização de atuação dependem do serviço.","review":true},{"id":"pergunta-341","sourceId":341,"title":"Os contadores e as empresas de contabilidade são obrigados à utilização do Certificado Digital?","originalTitle":"Os contadores e as empresas de contabilidade são obrigados à utilização do Certificado Digital?","sourcePage":98,"answer":"O contador deve seguir as regras do sistema e do perfil de representação. Obrigatoriedade de certificado e exigência de procuração são questões distintas; não se deve utilizar a credencial pessoal do cliente como forma de delegação.","review":true},{"id":"pergunta-342","sourceId":342,"title":"A senha do Certificado Digital pode ser informada para terceiros?","originalTitle":"A senha do Certificado Digital pode ser informada para terceiros?","sourcePage":98,"answer":"Não compartilhe a senha nem a chave privada do certificado. Quando outra pessoa precisar atuar, utilize as formas oficiais de procuração ou delegação e as credenciais próprias do representante.","review":false},{"id":"pergunta-343","sourceId":343,"title":"Quais certificados e perfis são aceitos no emissor de NFS-e utilizado?","originalTitle":"Os Certificados Digitais e-CNPJ e PJ NFS-e poderão ser utilizados para acessar o sistema da NFS-e da Prefeitura de São Paulo?","sourcePage":98,"answer":"Os tipos de certificado e perfis antigos citados no PDF precisam ser conferidos no emissor atual. Só utilize certificado válido e aceito pelo serviço; um perfil criado para sistema paulista não garante acesso ao de Aracaju.","review":true},{"id":"pergunta-344","sourceId":344,"title":"As Pessoas Jurídicas obrigadas à utilização do Certificado Digital também estão obrigadas à emissão da NFS-e por meio do WebService?","originalTitle":"As Pessoas Jurídicas obrigadas à utilização do Certificado Digital também estão obrigadas à emissão da NFS-e por meio do WebService?","sourcePage":98,"answer":"Autenticação por certificado não significa obrigação automática de integração por WebService ou API. A forma de emissão segue o regime e as regras técnicas e fiscais do emissor utilizado.","review":true}]},{"number":30,"id":"capitulo-30","short":"Domicílio Eletrônico","title":"Domicílio Eletrônico","description":"Cadastro, caixa postal, comunicações fiscais e acompanhamento de prazos.","subtitle":"Comunicações e processos tributários","icon":"mail","originalTitle":"DOMICÍLIO ELETRÔNICO DO CIDADÃO PAULISTANO - DEC","sourcePage":98,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"Legislação municipal no SLIM","url":"https://slim.aracaju.se.gov.br/home/legislacoes/"}],"topics":[{"id":"pergunta-346","sourceId":346,"title":"O que é o Domicílio Eletrônico de Aracaju?","originalTitle":"O que é o Domicílio Eletrônico do Cidadão Paulistano - DEC?","sourcePage":98,"answer":"O Domicílio Eletrônico é o canal de comunicação tributária previsto no sistema municipal. Em Aracaju, a SEMFAZ disponibiliza orientações de cadastro e caixa postal; DEC é a denominação do roteiro paulista.","review":false},{"id":"pergunta-347","sourceId":347,"title":"Quem deve se credenciar no Domicílio Eletrônico?","originalTitle":"Quem é obrigado a credenciar-se no DEC?","sourcePage":99,"answer":"O credenciamento obrigatório depende da norma de Aracaju e do perfil do contribuinte. Consulte as orientações atuais para pessoa física, empresa e representante, sem aplicar a lista de obrigados do DEC paulista.","review":true},{"id":"pergunta-348","sourceId":348,"title":"Como verificar as formas de autenticação aceitas?","originalTitle":"Qual o tipo de Certificação Digital aceito?","sourcePage":99,"answer":"A autenticação deve seguir as opções e os tipos aceitos no Domicílio Eletrônico de Aracaju. Confira o procedimento oficial de cadastro e acesso antes de adquirir ou utilizar um certificado.","review":true},{"id":"pergunta-349","sourceId":349,"title":"Quais os casos em que a SEMFAZ pode comunicar-se eletronicamente com o sujeito passivo?","originalTitle":"Quais os casos em que a Secretaria Municipal de Finanças e Desenvolvimento Econômico pode comunicar-se eletronicamente com o sujeito passivo?","sourcePage":99,"answer":"Comunicações podem envolver atos e processos tributários nos limites definidos pela norma municipal. Consulte regularmente a caixa postal e a identificação do processo para verificar o conteúdo e as providências exigidas.","review":true},{"id":"pergunta-350","sourceId":350,"title":"Qual a data em que a comunicação é considerada como realizada?","originalTitle":"Qual a data em que a comunicação é considerada como realizada?","sourcePage":99,"answer":"A data de ciência e o início de prazo dependem da regra municipal e do registro da comunicação. Consulte a informação do ato no sistema; recebimento de aviso por e-mail não deve ser confundido automaticamente com a data legal de ciência.","review":true},{"id":"pergunta-351","sourceId":351,"title":"Quais serviços estão disponíveis no Domicílio Eletrônico?","originalTitle":"Quais os serviços que serão disponibilizados ao sujeito passivo credenciado no DEC?","sourcePage":100,"answer":"O portal municipal apresenta orientações de cadastro, consulta da caixa postal e manifestação em processo fiscal eletrônico. Verifique os serviços habilitados para seu perfil e mantenha o acompanhamento das comunicações.","review":true}]},{"number":31,"id":"capitulo-31","short":"Atendimento e contatos","title":"Atendimento: contatos e endereços","description":"Canais da Fazenda municipal para orientação, serviços e encaminhamento de dúvidas.","subtitle":"Atendimento ao contribuinte","icon":"phone","originalTitle":"ANEXO - TELEFONES E ENDEREÇOS DAS SUBPREFEITURAS","sourcePage":100,"note":"","sources":[{"label":"Portal da SEMFAZ de Aracaju","url":"https://www.fazenda.aracaju.se.gov.br/"},{"label":"SLIM — serviços e licenciamento","url":"https://slim.aracaju.se.gov.br/"}],"topics":[]}]};
